quests[13860] = { id = 13860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At The Enemy's Gates", description = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Handler Dretch at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts, 3 Boneguard Lieutenants.", progress = "Have served alongside the crusaders in the Court of Bones?", completion = "The Argent Crusade has seen our resolve and they know that our warriors will see this through to the end.", sourceObjectiveStatus = "unverified-source-field" }
quests[13861] = { id = 13861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Before The Citadel", description = "Even as some of us labor on the tournament, our brothers prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Eadric the Pure at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders.", completion = "The Argent Crusade is heartened to have paladins like you fighting alongside us in the battle against the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[13862] = { id = 13862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Before The Citadel", description = "Even as some of us labor on the tournament, our brothers prepare the way for an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled argent charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Eadric the Pure at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders.", completion = "The Argent Crusade is heartened to have warriors like you fighting alongside us in the battle against the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[13863] = { id = 13863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Before The Citadel", description = "As some crusaders prepare for the tournament, they have sent others to make an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Crok Scourgebane at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders.", completion = "Everywhere we have met the Scourge, we have made them fear us, and this campaign is no different.", sourceObjectiveStatus = "unverified-source-field" }
quests[13864] = { id = 13864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Before The Citadel", description = "As some crusaders prepare for the tournament, they have sent others to make an assault on the enemy's stronghold of Icecrown Citadel.\n\nIn the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders.\n\nDo not fear the masses of boneguard footmen, {name}, for they can easily be trampled under your horse's hooves.", sourceObjective = "Crok Scourgebane at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders.", completion = "Everywhere we have fought the Scourge, we have taught them to fear us and this campaign will be no different.", sourceObjectiveStatus = "unverified-source-field" }
quests[13865] = { id = 13865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wet Work", description = "Listen carefully, {class}.\n\nThere are three leaders in this region who are commanding the elves, keeping their focus directed on the lumber camp. Slaying them will certainly cause panic and disarray, hopefully enough for us to successfully complete our mission.\n\nWhile you're at it, bringing down their scouts can only aid our cause.", sourceObjective = "Krokk wants you to kill Dorinar, Arminon, Endolar, and 12 Ashenvale Scouts.\n\nSpeak to Kadrak in Splintertree if you lose your Secret Signal Powder.", completion = "Well done, {class}.\n\nThey're in complete disarray. Just look at them!", sourceObjectiveStatus = "unverified-source-field" }
quests[13866] = { id = 13866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Ramparts!", description = "These woods may be silent but our enemies lurk behind every trunk. I've discovered many an orc with arrows in his back, his weapon still sheathed.\n\nIt is treacherous here, behind the lines, but we could use strong arms and sharp minds down at the Mor'shan Ramparts. Kadrak is preparing an offensive from there - he prefers action to talk. You and he will get along.\n\nSpeak with me when you are ready and I will fly you there.", sourceObjective = "Speak with Kulg Gorespatter at the Ashenvale/Azshara border to be transported to the Mor'shan Ramparts. Report to Kadrak when you arrive.", completion = "You are just in time, {class}. Old Kulg has been slinking around those woods too long. He grows too cautious, jumping at shadows. We will fear this forest no longer - the time has come to subdue Ashenvale once and for all!", sourceObjectiveStatus = "unverified-source-field" }
quests[13867] = { id = 13867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Furbolg Threat", description = "Directly to the north of Astranaar are the Thistlefur furbolg. My scouts report that their numbers have grown greatly over the past few months. If they grow too great, they may find the courage to attack Astranaar directly!\n\nGo to Thistlefur Village and kill as many of their kind as you can.\n\nI shall remain here in Astranaar and await word from you. Elune be with you, {class}.", sourceObjective = "Slay any 15 furbolg at Thistlefur Village in Ashenvale.", completion = "Well done, {name}.\n\nWe are under constant threat from the furbolg. Hopefully this will keep them at bay for a bit longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[13868] = { id = 13868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupting Influence?", description = "As you search through the belongings of the dead furbolg lying before you, a small charm, very obviously created by trolls,  spills out onto the ground.\n\nTouching the charm, you immediately get a sense that something is not right about the wood. A feeling of unease, of corruption, permeates the object.\n\nWrapping it in some spare cloth, you put it in your pack and resolve to show it to Raene Wolfrunner when next you find yourself in Astranaar.", sourceObjective = "Deliver the Troll Charm to Raene Wolfrunner at Astranaar in Ashenvale.", progress = "What's troubling you, {class}?", completion = "A troll charm? What are the furbolg doing with such a thing?\n\nYou're right, it does have a feeling of corruption about it... even I can sense that.\n\nThere's someone here who might be able to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[13869] = { id = 13869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover the Remains", description = "While what the satyrs have done to the trees is horrible, nothing compares to the mass slaughter that the orcs have been engaging in!\n\n<The ancient shakes with visible rage, his leaves falling all around you.>\n\n{race}, I would have you head across the road here at the lumber camp and recover the remains of those trees, treants, and ancients that the Horde have hewn down in their prime.", sourceObjective = "Collect 10 Warsong Lumber.", progress = "Have you the remains, little one?", completion = "I have lived a very long time in peace with the forest, but what these orc-things are doing makes me want to feed them back to the ground!\n\nI will put this wood to rest now. Thank you for this kindness, {name}. I will never forget.", sourceObjectiveStatus = "unverified-source-field" }
quests[13870] = { id = 13870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As Good as it Gets", description = "Well, {class}, this is as good as it gets.\n\nThe elves are scrambling to recover from your recent deeds. There's no better time to break into the lumber camp!\n\nMake your way in and speak with Overseer Gorthak. He'll instruct you as to how best escort the diplomat to safety.\n\nGood luck!", sourceObjective = "Krokk wants you to enter the Warsong Lumber Camp and speak with Overseer Gorthak.", completion = "<Gorthak sighs disappointedly.>\n\nIf only you'd arrived an hour ago....\n\nThe diplomat suffered mortal wounds at the hands of an elf assassin.\n\nHow the enemy was able to infiltrate the camp undetected remains a mystery.", sourceObjectiveStatus = "unverified-source-field" }
quests[13871] = { id = 13871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Security!", description = "It's not as like I haven't got enough to think about here!\n\nKeeping this place operational is hard enough without constant elf and draenei harassment.\n\nNow, on top of everything, there's an assassin lurking around the camp who's killed an important diplomat... on my watch!\n\nWhoever it is couldn't have gotten far, {class}. Scour the camp until you find her and then avenge the diplomat!\n\nAt least I can bring the assassin's head with me when I have to answer to Hellscream.", sourceObjective = "Overseer Gorthak wants you to bring him the Kaldorei Assassin's Head.", progress = "I want to know one thing, {race}.\n\nIs that assassin dead?", completion = "Well done, {class}.\n\nOne last request - it would probably be best if none of my laborers knew this assassin ever existed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13872] = { id = 13872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen Wisdom", description = "The man standing right across from me is known as Hephaestus Pilgrim. He's one of the worgen.\n\nHe and his sister came to Astranaar not long ago looking for a place to live. From what little I've been able to glean, he's interested in trying to help the Earthen Ring with the Cataclysm. His sister is even more powerful. She's gone east to try and help the shaman deal with the volcano.\n\nPerhaps he can help. Take the charm over to him and see what he thinks.", sourceObjective = "Take the Troll Charm to Hephaestus Pilgrim at Astranaar in Ashenvale.", progress = "<The {race} gives you a blank look as you walk up to him.>", completion = "<Looking down at the wooden carving in your extended hand, the {race} reaches out to take it.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13873] = { id = 13873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sheelah's Last Wish", description = "I... I cannot believe she's gone. It all happened so fast....\n\nI understand that I have you to thank for avenging my mistress. For that, you have my gratitude, and that of Silvermoon.\n\nIn her wisdom, my lady foresaw this end. She prepared a missive to be delivered in the event that something happened to her.\n\nWe were to join an Orgrimmar retinue at the crossroads just north of here. Please, {race}, meet them in our stead and see that the message is delivered.", sourceObjective = "Guardian Menerin wants you to deliver the Sealed Missive to Guardian Gurtar.\n\nProvided item:", completion = "<Gurtar listens as you inform him of Sheelah's passing.>\n\nI'll deliver this to Hellscream personally, {race}.\n\nIn the meantime, there's something I need you to do for me....", sourceObjectiveStatus = "unverified-source-field" }
quests[13874] = { id = 13874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Not-So-Charmed Life", description = "The furbolg covet that which does not belong to them.\n\n<Hephaestus turns the charm over in his hand and then discards it.>\n\nThere's a property to the carving that slowly corrupts those that aren't trolls. As I understand it, the furbolg have done this sort of thing before. Some never learn.\n\nNo doubt they hoard most of the charms in Thistlefur Hold above their village to the north.", sourceObjective = "Collect 8 Troll Charms.", progress = "Do you think that you retrieved all of the troll charms from Thistlefur Hold?\n\nIf any are left behind, the Thistlefur tribe will continue to be influenced by them, and eventually they will attack this place.", completion = "<Hephaestus nods slowly as he looks you straight in the eye.>\n\nYou've likely saved the Thistlefur from themselves, at least in the short run.  If they can keep from stealing objects of power that don't belong to them, that is.\n\nI understand that the night elves are having problems with the other furbolg tribe to the south. That's something that Raene is going to want to speak to you about.\n\nHowever, there are more immediate concerns that I would ask for your help with.", sourceObjectiveStatus = "unverified-source-field" }
quests[13875] = { id = 13875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurtar's Request", description = "I have a bit of a personal request for you, {class}.\n\nIt has been many moons since I have seen my love, Draaka. It will be many more before we are able to be together again. I fear that as time passes, her love for me will wane.\n\nThis braid has special meaning to the two of us, as do Thorned Bloodcups, the flower of this region.\n\n I ask that you pluck the flowers and weave them into this twine, then present the gift to Draaka on my behalf.", sourceObjective = "Guardian Gurtar wants you to give the Bloodcup Braid to Draaka in Splintertree.", progress = "Hello, {name}.", completion = "<Recognizing at once the nature of the gift, Draaka begins to weep.>\n\nOh, {name}. Thank you for this gift! It means more than you could know.\n\nHe hasn't forgotten...", sourceObjectiveStatus = "unverified-source-field" }
quests[13876] = { id = 13876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Far Gone", description = "Yes, I speak your tongue, {race}.\n\nWe furbolg have been through this kind of corruption before. Not long ago our leader stole the Idol of Remulos. The demon-tainted thing ensorcelled the entire tribe and our redemption was barely delivered by a druid known as Broll Bearmantle.\n\nBut this time, we did not steal. The trolls of Zoram'gar gave us the charms as a sign of friendship. A deadly friendship it would seem.\n\nOur chief, Dal Bloodclaw, is too far gone. Enter the hold and return with his charms.", sourceObjective = "Obtain Bloodclaw's Collection.", progress = "Well? The future of the Thistlefur rests upon your shoulders, {race}.", completion = "What was done had to be done. As our leader, Dal's sickness from the troll charms was destroying us.\n\nIt was better for the health and dignity of the tribe that it was you, outsider. This way there will be no civil war amongst us and we will easily find new leadership... hopefully one that does not have a tendency to so easily trust outsiders. Perhaps I am guilty of this as well?\n\nHere, allow me to repay the debt we owe you before we part ways forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[13877] = { id = 13877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go With The Flow", description = "<The worgen stares at you intently before launching into his request.>\n\nThe volcano threatens to engulf all of Ashenvale if we do not act quickly. Let me assure you, this was no natural eruption.\n\nMy sister, Sabina, is powerful. She has gone east to the edge of Thunder Peak's lava flow, just north of the road to enlist the aid of the other elements against the fire lord that has caused this destruction.\n\n{name}, go to her and give her what assistance you can.", sourceObjective = "Speak with Sabina Pilgrim at the southern edge of Thunder Peak's lava flow in Ashenvale.", completion = "My brother must have sent you. He wouldn't have done so unless you are capable of doing what must be done.\n\nFor all of our sakes I hope that he's right.\n\nThe elementals here are now my allies. You must do as they ask if we are to prevent the destruction of the rest of Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[13878] = { id = 13878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through Fire and Flames", description = "Help me, {class}! Piggy men come burn stables - fire! Fire!\n\n<Dorak wails incoherently before you can settle him down.>\n\nWolves still chained inside. Someone's got to save the wee wolves!", sourceObjective = "Break the chains to free the wolves from the burning stables.", progress = "Hot!", completion = "You save the wolves! So brave! Someday, maybe you get a wolf just like that to ride.\n\n<Dorak looks at the burning stables, then at the nearby river.>\n\nWhat should I do now?", sourceObjectiveStatus = "unverified-source-field" }
quests[13879] = { id = 13879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Peak", description = "Greetings, {class}.\n\nCongratulations on your victorious assault on Astranaar. The elves shall not soon forget the humiliation they have suffered at your hand.\n\nBut you must know, the elves are not the only obstacle to the Horde's conquering of Ashenvale....\n\nTo the east, a shaman of the Earthen Ring requires assistance with yet another crisis. You can find him near the base of the volcano, Thunder Peak.", sourceObjective = "Broyk wants you to find Stikwad at Thunder Peak.", completion = "<The goblin stares at you and blinks several times before speaking.>\n\nThe spirits whispered that help would soon arrive.\n\nPardon my surprise, but I was hoping the spirits would guide someone a little more... heroic.\n\nThese elementals are trusted allies. Listen to them and do their bidding. If we fail, there will remain nothing in Ashenvale worth fighting for.", sourceObjectiveStatus = "unverified-source-field" }
quests[13880] = { id = 13880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot Lava", description = "<The massive earth elemental gazes down upon you.>\n\nThe flow of the lava must be stopped if we are to prevail. I will grant to you a portion of my power. Use it to fill the lava fissures!", sourceObjective = "Use the Gift of the Earth to fill 8 Lava Fissures.", progress = "Done?", completion = "Well done, {race}. Lord Magmathar's fire is now trapped, restrained within the earth once more.", sourceObjectiveStatus = "unverified-source-field" }
quests[13881] = { id = 13881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consumed", description = "My first concern right now is for the thistle bear families who call what's left of these woods home. Just to our south, beyond the bear shrine, an entire generation has fallen ill. Gruesomely ill.\n\n{name}, I don't know what they're suffering from, but it's consumed them from within. It pains me that a whole generation is beyond saving, but we've got to kill them off so that the earth can reclaim their bodies.\n\nMore importantly, we need to find the source. Investigate the shallow lake they drink from!", sourceObjective = "Kill 6 Consumed Thistle Bears and investigate the lake they're drinking from.", completion = "<Kathrena recoils at your description of the ravaged animals and the cruel device at the bottom of the lake.>\n\n{name}, this is terrible. What is that thing, and how did it get there? Something is devouring these animals, physically and spiritually. I had suspected the satyrs or some sort of disease was the culprit, but this is shaping up to be something... unnatural.", sourceObjectiveStatus = "unverified-source-field" }
quests[13882] = { id = 13882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seeds of Life", description = "Something is trying to devour the life of Darkshore from within! I'll ask around to learn more about the - thing - you discovered in the lake. Meanwhile, we need to protect the local wildlife from further harm.\n\nCan you gather some materials for me? I'll need life in all its incarnations. Talk to Onu here in the grove to acquire a Seed of the Earth. Capture a Darkshore Wisp floating amongst the trees and we'll have a Seed of the Sky. Find a Seed of the Sea within seashells along the coast, west of here.", sourceObjective = "Gather a Seed of the Earth, a Seed of the Sea, and a Seed of the Sky.", progress = "Life is powerful, {name}. Concentrated in its purest form, it can overcome anything. Someday, even Darkshore will heal from its wounds. Did you find everything I need?", completion = "Perfect, this is everything. Did you have fun collecting the wisp? I used to chase the wisps around Ashenvale when I was just a girl.\n\n<Lost in memories for a moment, Kathrena suddenly grows somber.>\n\nI'm afraid I've found out what we're dealing with.", sourceObjectiveStatus = "unverified-source-field" }
quests[13883] = { id = 13883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lousy Pieces of Ship", description = "Shoddy workmanship! There's no other explanation...\n\nThese ships must've been constructed in a hurry. Entire pieces of armor plating are falling off without even sustaining a direct hit!\n\nI'll show them how it is to be done. But first, I need you to recover the pieces from the sea floor.\n\nReturn to me with the pieces and I'll do the rest.", sourceObjective = "Recover 10 pieces of Sunken Scrap Metal.", progress = "Were you able to recover that armor plating, {race}?", completion = "Good work, {race}.\n\nI'll show them how an armored ship should be built!", sourceObjectiveStatus = "unverified-source-field" }
quests[13884] = { id = 13884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put Out The Fire", description = "Lord Magmathar's minions must first be dealt with if we're to retake this area and put a stop to the fiery destruction of the forest.\n\nThe lava ragers on the flow to the north are strengthened by being on their own element. I fear that on your own, you won't have much chance against them.\n\nWhen you are ready, speak to me again, and I will summon one of my own to assist you.", sourceObjective = "Slay 10 Lava Ragers. If you need another Freezing Surger, speak with Arctanus.", completion = "You acquitted yourself well in battle on the field. However, I'm afraid that Lord Magmathar has taken notice of you and the destruction that you've wreaked upon his minions.\n\nYou will have to deal with him or he is sure to burn you alive, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13885] = { id = 13885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Darkshore", description = "Now that we know our preventative measures work, we should cover as much ground as possible.\n\nI've arranged to commandeer one of our hippogryphs, but I can't do this alone. Talk to my friend Orseus, next to the flight master right outside the grove here. Let him know when you're ready and I'll meet you there. We'll canvas Darkshore from the air and protect as many animals as we can!", sourceObjective = "Talk to Orseus outside the Grove of the Ancients and mount a hippogryph. From the air, protect 8 Whitetail Deer, 8 Grizzled Thistle Bears, and 8 Moonstalker Matriarchs/Sires from the consumption.", completion = "So the animals are safe, then. Thank you, thank you!\n\nBut now it's time to turn our attention to the source.", sourceObjectiveStatus = "unverified-source-field" }
quests[13886] = { id = 13886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "The time has come, {name}. When you have steeled yourself we will speak again and I will summon forth a whirling vortex to speed your way up to the skies over Thunder Peak.\n\nChannel the power of the Earthen Ring through the elemental to slay Lord Magmathar so that we may bring him into balance once more.", sourceObjective = "Use the powers of the Whirling Vortex to slay Lord Magmathar.", completion = "It is done. The power of fire is subdued and the four elements are returned to harmony.\n\nYou have saved the rest of Ashenvale through your brave and selfless actions, {name}. You have our eternal thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[13887] = { id = 13887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venomhide Eggs", description = "Now that you've built up an immunity to venomhide toxin, you can safely handle the animals and their eggs. Venomhides are vicious and must be trained from the moment they hatch.\n\nIf you want to ride one, you'll need an unhatched egg. Scattered throughout the Marshlands are a number of ravasaur nests. Look for the eggs with lighter colored shells -- those are the ones that will hatch venomhides.\n\nIf you bring me several of the eggs, I'll allow you to keep one and raise its hatchling, with my guidance.", sourceObjective = "Bring 4 Venomhide Ravasaur Eggs to Mor'vek in the southeast part of the Marshlands.", progress = "Did you find those eggs?", completion = "Good work. Honestly, I'm amazed you were able to find this many. With each clutch, they seem fewer in number.\n\nI'll let you raise one of the freshly-hatched venomhides. It shouldn't be shy about letting you know what it needs.", sourceObjectiveStatus = "unverified-source-field" }
quests[13888] = { id = 13888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "The time has come, {name}. When you have steeled yourself we will speak again and I will summon forth a whirling vortex to speed your way up to the skies over Thunder Peak.\n\nChannel the power of the Earthen Ring through the elemental to slay Lord Magmathar so that we may bring him into balance once more.", sourceObjective = "Use the powers of the Whirling Vortex to slay Lord Magmathar.", completion = "You've done it! The spirits were right after all!\n\nThe power of fire is subdued and the four elements are returned to harmony.\n\nThe rest of Ashenvale is spared this fiery fate. You have the eternal thanks of the Earthen Ring.", sourceObjectiveStatus = "unverified-source-field" }
quests[13889] = { id = 13889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry, Hungry Hatchling", description = "The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.\n\nThe drawings are rough, but you can make out the shapes of diemetradons, stegodons, and pterrordaxes. As the raptor finishes the sketch, it looks up at you, bares its teeth, and makes a biting motion.\n\nYour venomhide hatchling must be craving fresh meat from these animals. Find and kill any type of diematradon, stegodon, or pterrordax in Un'Goro Crater and feed its meat to your hungry hatchling.", sourceObjective = "Your Venomhide Hatchling wants you to feed it 15 pieces of Fresh Dinosaur Meat.", progress = "The venomhide hatchling licks its lips and tilts its head to the side.", completion = "The venomhide hatchling seems satisfied with the giant meal you've provided, but there's no way of telling when it will be hungry again.", sourceObjectiveStatus = "unverified-source-field" }
quests[13890] = { id = 13890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep the Fires Burning", description = "This is no small task, {race}!\n\nWe have more ships arriving, and without the lighthouse they'll be lost - or worse! You are hereby charged with keeping its fire lit.\n\nCollect the blubber from the hydras in these waters, then bring it to the forge here to melt it into oil.\n\nThrowing that oil on the lighthouse fire will buy us the time we need.", sourceObjective = "Commander Grimfang at Zoram'gar wants you to pour Mystlash Hydra Oil on the lighthouse fire.", progress = "Well, {class}...\n\nHave you done as I asked?", completion = "Nice work, {race}!\n\nNo more ships will run aground, thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13891] = { id = 13891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Devourer of Darkshore", description = "Now that the creatures of Darkshore are safe, let's turn our attention to the artifact you found in the lake. I believe it's the work of a minion of the Old Gods. We'll fight these fiends using the very lifegiving energies of Darkshore itself! Take the Lifebringer Sapling to the shore of the shallow lake to the south of here. Wave it over the waters of the lake and it should disable that ancient artifact.\n\nBe careful, {name}. The artifact is likely to be guarded by who-knows-what.", sourceObjective = "Use the Lifebringer Sapling on the shore of the shallow lake south of the Grove of the Ancients to destroy the Devouring Artifact and its guardian.", progress = "I'm afraid to ask, {name}. Is the artifact destroyed? What about its guardian?", completion = "Love of Elune, look at you. That must've been some fight! You're covered in what looks like... chowder.\n\nIf a mere minion could cause so much agony here in Darkshore, I can't even imagine the suffering that a true Old One could bring about.\n\nWell, at least the animals are safe for now. I will plant the sapling you created to help rebuild this shattered land. Thank you, {name}! I'd give you a hug but, you know. Chowder.", sourceObjectiveStatus = "unverified-source-field" }
quests[13892] = { id = 13892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Tracks", description = "To the southwest lies the corpse of a being somehow related to the Old Gods that the Twilight's Hammer cultists worship.\n\nHe was defeated before our time -- if not by the Titans themselves, certainly by one of their creations.\n\nWe've noted an increase in cult activity in that area which can only mean something terrible is amiss.\n\nWe're going to need to find out what they're planning to do there and why.  Take this figurine, it'll help you avoid being detected while you gather intelligence.", sourceObjective = "Sneak into the Master's Glaive using the Panther Figurine and spy on the Twilight's Hammer.", completion = "This is dire news, {name}.  If you are correct, then we'd best act swiftly and decisively.\n\nWe cannot allow this \"Soggoth\" to be brought back to life.", sourceObjectiveStatus = "unverified-source-field" }
quests[13893] = { id = 13893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soggoth and Kronn", description = "The Master's Glaive was the site of an ancient battle, {name}.  The titans sent twenty of their stone giants against Soggoth.\n\nOf those twenty giants, one survived.\n\nThe tablets say that Kronn, the largest of the stone giants allowed himself to be entangled by Soggoth's tendrils -- just long enough to be lifted close enough to the creature's skull... within reach of his mighty sword.\n\nIt's a good thing he's dead... we don't really have twenty stone giants lying around to stop him again.", sourceObjective = "Return to Larien at the Grove of the Ancients with the information you've obtained.", completion = "The dwarf's story is unsettling... yet informative.  It seems we have few options left.", sourceObjectiveStatus = "unverified-source-field" }
quests[13895] = { id = 13895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slumbering Ancients", description = "We may not have twenty stone giants to take on our enemy, but we giants of ancient lumber are as strong as any rock.\n\nLook around you, {race}.  My kindred sleep... yet they will heed the keeper's horn when the time of need is upon them.\n\nYou will find Aros, the keeper of the grove, beyond the bridge northeast of here.\n\nTell him the urgency of our situation.", sourceObjective = "Find Aros northeast of the Grove of the Ancients in Darkshore.", completion = "Aros's body appears to be lifeless yet still warm.  Perhaps his killers are nearby.", sourceObjectiveStatus = "unverified-source-field" }
quests[13896] = { id = 13896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unearthed Knowledge", description = "Listen, {name}.  We need to learn more about what we're up against.\n\nTo the southwest, beyond the Master's Glaive, there is a group of dwarven prospectors who were excavating the nearby ruins.\n\nPerhaps they have uncovered knowledge that is useful to us in this matter.", sourceObjective = "Speak to Archaeologist Groff at Remtravel's Excavation.", completion = "Oh, we know a thing or two about this Soggoth.  The question is... do you really want to know?", sourceObjectiveStatus = "unverified-source-field" }
quests[13897] = { id = 13897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Darkshore", description = "The ancients of the grove have come to our aid, {name}.  I can see through their eyes even as we speak.\n\nThe Twilight's Hammer has been forced to hasten their ritual and have thus only managed to resurrect but a remnant of dread Soggoth.\n\nDestroy it before it's too late, {name}.  I am needed elsewhere.\n\nReturn to the druids at the Grove of the Ancients when it is all over they will direct you further.", sourceObjective = "Slay the Avatar of Soggoth at the Master's Glaive.", completion = "We can finally rest here now, {name}.  It appears Darkshore has been saved -- and we have you to thank for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13898] = { id = 13898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tides Turn Against Us", description = "We cannot let the naga get away with this, {name}.  Slaying the keeper of the grove amounts to a declaration of war.\n\nYou'll find their den inside a cave on the island of Naj'vel, far to the southwest.\n\nI want you to send them a clear message.", sourceObjective = "Slay 8 Darkscale Myrmidons.", completion = "Well done, {name}.  The naga seek the destruction and subjugation of all surface-dwellers -- do not hesitate to drive them out of our lands and back into the shadowy ocean depths where they belong.", sourceObjectiveStatus = "unverified-source-field" }
quests[13899] = { id = 13899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkscale Warlord", description = "If the naga want to throw in their lot with the Twilight's Hammer, then may Elune have mercy on them.\n\nGo into their lair in the island of Nazj'vel and find their leader, the naga warlord known only as Wrathspine.\n\nPerhaps the horn of the ancients can still be saved.", sourceObjective = "Slay Warlord Wrathspine inside Nazj'vel.", completion = "The warlord doesn't seem to have the horn on him.  Perhaps he was telling the truth.", sourceObjectiveStatus = "unverified-source-field" }
quests[13900] = { id = 13900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Offering to Azshara", description = "The warlord said the horn of the ancients was being offered to Azshara above Nazj'vel.\n\nPerhaps it's not too late to save the ancient relic from being destroyed.", sourceObjective = "Stop the Darkscale Priestesses from offering the Horn of the Ancients to Azshara above Nazj'vel.", progress = "Hail, {name}.", completion = "You've done well, {name}.  Unfortunately the battle is far from over.", sourceObjectiveStatus = "unverified-source-field" }
quests[13901] = { id = 13901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Despair", description = "There is more to this naga problem than meets the eye, {class}.  It appears that the issue will not be resolved by merely thinning their numbers. To humble them, a more severe impression must be made.\n\nTravel to the northern end of Zoram Strand and enter Blackfathom Deep. Once there, demonstrate to the naga that their presence in this region will no longer be tolerated!", sourceObjective = "Kill 6 Blackfathom Tide Priestesses.", completion = "Excellent!\n\nLet the naga retreat back into the seas where they belong!", sourceObjectiveStatus = "unverified-source-field" }
quests[13902] = { id = 13902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mounting the Offensive", description = "Our work in Darkshore is not yet done.  We might have stopped the landmass from shattering, but our enemies still have a strong presence in the area.\n\nI want you to contact a group of druids at the Grove of the Ancients, far to the south.  They are led by an old friend of mine, Balren of the Claw.\n\nTell them that the time has come to take the battle to our foes.  I will come to aid them as soon as we stabilize the area.", sourceObjective = "Speak to Balren of the Claw at the Grove of the Ancients in Darkshore.", completion = "If Malfurion placed his trust in you, then so shall I.  You'll find that our enemies greatly outnumber us this far south.\n\nWhere brute force and numbers fail us, strategy and guile will prove our biggest advantages.", sourceObjectiveStatus = "unverified-source-field" }
quests[13903] = { id = 13903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorishi Grub", description = "The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.\n\nThe hatchling's drawings seem to resemble various types of large insects, perhaps the gorishi silithids. The hatchling finishes his picture, then gestures at it with one short arm, snaps its jaws, and licks its lips.\n\nIt must want you to go to the Slithering Scar, in the center of the southern part of Un'Goro Crater, and gather silithid meat. When you have the meat, feed it to your hungry hatchling.", sourceObjective = "Your Venomhide Hatchling wants you to feed it 10 Silithid Meat.", progress = "The hatchling cocks its head and looks at you.", completion = "Your venomhide hatchling flashes you a toothy smile and then settles in for a nap.", sourceObjectiveStatus = "unverified-source-field" }
quests[13904] = { id = 13904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poached, Scrambled, Or Raw?", description = "The venomhide hatchling's stomach growls as it gestures to get your attention. It begins scratching pictures of silithids into the dirt, adding small ovals underneath them. It looks at you hopefully and gestures at the circles.\n\nThey can only mean silithid eggs. The Noxious Lair, in western Tanaris and near the border with Un'Goro Crater, would probably be a great place to find the eggs your little hatchling wants.", sourceObjective = "Your Venomhide Hatchling wants you to feed it 12 Silithid Eggs.", progress = "The hatchling looks at you.", completion = "Your hatchling licks its lips after devouring the meal of silithid eggs. For a moment, you think it seems disappointed that feeding time has come to an end.", sourceObjectiveStatus = "unverified-source-field" }
quests[13905] = { id = 13905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searing Roc Feathers", description = "The hatchling looks at you for a moment, almost as if wondering whether you'll understand. It scrawls a picture of a pair of feathers in the dirt, then points with one claw to the bindings at its elbows and knees.\n\nIt doesn't seem hungry, but what could the feathers be for?\n\nIt must want them for adornments like the ones you've seen on other raptors. The largest feathers come from the searing rocs that congregate around the bones of large creatures in western Tanaris, northeast of Thistleshrub Valley.", sourceObjective = "Your Venomhide Hatchling wants you to get 5 pieces of Searing Roc Plumage.", progress = "Your venomhide hatchling looks at you with anticipation.", completion = "The venomhide hatchling accepts the feathers and begins looking them over, holding several up to its armbands.", sourceObjectiveStatus = "unverified-source-field" }
quests[13906] = { id = 13906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Grow Up So Fast", description = "With your expert feeding and care, your venomhide hatchling will grow quickly. As they grow, their hatchling teeth will be replaced by adult teeth. If you keep the teeth shed by your hatchling as it grows, you'll have an easy way to tell when it's mature enough to be trained as a mount.\n\nYour venomhide will let you know what it needs, so pay close attention. When it has shed all of its baby teeth, return to me with your venomhide and the materials for your saddle and I'll do the rest.", sourceObjective = "Return 20 Venomhide Baby Teeth,  the Venomhide Hatchling, 20 Runecloth, 20 Rugged Leather, and 80 gold to Mor'vek in the southeastern part of the Marshlands in Un'Goro Crater.", progress = "Have you been taking good care of that raptor?", completion = "It looks like both of you have managed to do some growing without killing one another.\n\nThere, everything's finished. I've trained your venomhide ravasaur to respond when you blow this whistle.\n\nFew have the dedication to hand-feed and raise a venomhide, but they're well worth the effort.", sourceObjectiveStatus = "unverified-source-field" }
quests[13907] = { id = 13907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweeping Clean the Ruins", description = "The big beards at Ironforge sent me here to check on Remtravel's dig the moment they got word of the disaster. Look at it! Precious artifacts washed to sea, months of tedious digging undone in a moment.\n\nWhen the tidal waves hit, they demolished the murloc encampments along the shore. Good news? Naw, not with my luck. The survivors are squatting in the shelter of the ruins, and they're doing more damage than the elements ever could. Would you mind getting your waders on and taking care of things?", sourceObjective = "Kill 10 of any combination of Greymist Oracles or Greymist Refugees squatting within Remtravel's Excavation.", completion = "Bravo, {name}! Now let's take a look-see at our new situation.\n\nWhat? MORE murlocs? I swear on my stones, the more murlocs you kill, the more murlocs appear. Is it just me? We're going to need a new approach.", sourceObjectiveStatus = "unverified-source-field" }
quests[13908] = { id = 13908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gearing Up To Ride", description = "Your venomhide is strong and healthy and you've developed quite a bond. You'll be ready to ride him once I've completed your saddle and bridle. Just like you, they have to be specially conditioned to stand up to the toxins the raptor produces.\n\nAll you'll need to do is bring me some rugged leather, runecloth, and money to buy the rest of the supplies and I'll have that saddle for you in no time.", sourceObjective = "Bring 20 Rugged Leather, 20 Runecloth, and 80 gold to Mor'vek in the southeast part of the Marshlands in Un'Goro Crater.", sourceObjectiveStatus = "unverified-source-field" }
quests[13909] = { id = 13909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Got Some Flotsam?", description = "We can figure this out, {name}. We just need some Dwarven ingenuity. Think, Groffy, think!\n\nThese murlocs are just looking for a home, right? Let's do something constructive. I mean that literally.\n\nAll sorts of debris was washed ashore during the catastrophe, and some of the decimated murloc hovels may still be salvageable. Run along the shore here and gather up any building materials fit for a murloc. That's an admittedly low standard.", sourceObjective = "Collect 5 pieces of Salvageable Greymist Wreckage from along the shore and in the water near the Remtravel Excavation.", progress = "Wet enough for ya?", completion = "<Archaeologist Groff picks through the wreckage.>\n\nWell, not much here that don't look stepped on, sat on, or soaked in a toilet. But toss some thatch on top and it'll do.\n\nTell me, {name}, do you consider yourself an architect?", sourceObjectiveStatus = "unverified-source-field" }
quests[13910] = { id = 13910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Home", description = "Can we build it? Yes we can! Just west of the dig site I planted a banner on the shore. The sand is firm and it's as good a site as any. Take my tools and the parts you collected and build these ornery pests a different place to live.", sourceObjective = "Build a murloc hovel at a site Groff marked with a flag on the nearby shore.", progress = "How goes our new seaside condo?", completion = "Har har, that sounds like quite a heap you built there. Did they take to it? Good, good! Let's see if my plan comes to fruition.\n\n<Archaeologist Groff watches as scores of murlocs stream down the beach, pouring into the hovel from all corners of the compass. Gradually his brows knit together.>\n\nWhat have I done?", sourceObjectiveStatus = "unverified-source-field" }
quests[13911] = { id = 13911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Absent-Minded Prospector", description = "Who are you again? {name}? Have we met? If you're here from the League, you can tell them I'm not leaving! Not without my find. I had it, right in my hands! Then the screaming. Then the wetness.\n\nListen here whos-yer-name, I documented the whole thing in my journal the day the tidal wave hit. And I know just where I left it! The journal. Not the find. Help me get the one so we can get the other! Or vice-versa! Do you follow? Follow me!", sourceObjective = "Escort the confused Prospector Remtravel to his missing journal. Talk to Jr. Archaeologist Ferd at the dig site when you're done.", progress = "Prospector Remtravel is an unsung hero! Like any great explorer, he is prone to wandering aimlessly.", completion = "Ah, you've helped the Prospector find his missing journal! To think it was here all along.\n\nSomeday you'll have to show me this other set of ruins he's always going on about.", sourceObjectiveStatus = "unverified-source-field" }
quests[13912] = { id = 13912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swamped Secrets", description = "Underneath Remtravel's forgetful exterior is the mind of a genius, an enigma cloaked in senility. But I'm not about to give up on the old man. Look at what I found in his notes... not there... no, that's a shopping list... Here, on the page where he's trying to figure out what year it is: The Disc!\n\nWe think this Titan artifact is some sort of encrypted storage wheel. We were carefully unearthing it when the disaster hit, but hopefully it's still in the ruins. Dive in and grab it for me!", sourceObjective = "Find a Mud-Crusted Ancient Disc from within the nearby ruins.", progress = "Did you find it? Groff wants to clear out of these ruins as soon as possible!", completion = "Spectacular! Good work, {name}. I'm sure Remtravel would thank you himself if he could remember your name.\n\nLook at the surface of the disc - these microscopic etchings - this is amazing. I'm certain this strange wheel holds information, if only we could read it...", sourceObjectiveStatus = "unverified-source-field" }
quests[13913] = { id = 13913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Took Our Gnomes", description = "The gnome explosives squad we requested from Tinker Town arrived last week. Just in time to face an assault by the Horde. We lost a lot of soldiers that day. Most of the gnome team was taken as well. Now we're neck deep in Horde, Silverwind Refuge has been lost and we're down a dozen gnomes.\n\nI'm begging for your help here, {name}. Travel east to Silverwind Refuge and look for any gnome survivors. They were all carted off by a big, merciless orc named Thundrak. Find him and you'll find our gnomes.", sourceObjective = "Rescue Boog the \"Gear Whisperer\" and Minx from Painmaster Thundrak's Wagon of Unending Agony.", completion = "Thank you, {name}. Grim news you bring of the rest of the gnome team, but at least you managed to save a few. For that I am grateful.", sourceObjectiveStatus = "unverified-source-field" }
quests[13914] = { id = 13914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searing Roc Feathers", description = "The hatchling looks at you for a moment, almost as if wondering whether you'll understand. It scrawls a picture of a pair of feathers in the dirt, then points with one claw to the bindings at its elbows and knees.\n\nIt doesn't seem hungry, but what could the feathers be for?\n\nIt must want them for adornments like the ones you've seen on other raptors. The largest feathers come from the searing rocs that congregate around the bones of large creatures in western Tanaris, northeast of Thistleshrub Valley.", sourceObjective = "Your Venomhide Hatchling wants you to get 5 pieces of Searing Roc Plumage.", progress = "Your venomhide hatchling looks at you with anticipation.", completion = "The venomhide hatchling accepts the feathers and begins looking them over, holding several up to its armbands.", sourceObjectiveStatus = "unverified-source-field" }
quests[13915] = { id = 13915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry, Hungry Hatchling", description = "The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.\n\nThe drawings are rough, but you can make out the shapes of diemetradons, stegodons, and pterrordaxes. As the raptor finishes the sketch, it looks up at you, bares its teeth, and makes a biting motion.\n\nYour venomhide hatchling must be craving fresh meat from these animals. Find and kill any type of diematradon, stegodon, or pterrordax in Un'Goro Crater and feed its meat to your hungry hatchling.", sourceObjective = "Your Venomhide Hatchling wants you to feed it 15 pieces of Fresh Dinosaur Meat.", progress = "The venomhide hatchling licks its lips and tilts its head to the side.", completion = "The venomhide hatchling seems satisfied with the giant meal you've provided, but there's no way of telling when it will be hungry again.", sourceObjectiveStatus = "unverified-source-field" }
quests[13916] = { id = 13916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poached, Scrambled, Or Raw?", description = "The venomhide hatchling's stomach growls as it gestures to get your attention. It begins scratching pictures of silithids into the dirt, adding small ovals underneath them. It looks at you hopefully and gestures at the circles.\n\nThey can only mean silithid eggs. The Noxious Lair, in western Tanaris and near the border with Un'Goro Crater, would probably be a great place to find the eggs your little hatchling wants.", sourceObjective = "Your Venomhide Hatchling wants you to feed it 12 Silithid Eggs.", progress = "The hatchling looks at you.", completion = "Your hatchling licks its lips after devouring the meal of silithid eggs. For a moment, you think it seems disappointed that feeding time has come to an end.", sourceObjectiveStatus = "unverified-source-field" }
quests[13917] = { id = 13917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorishi Grub", description = "The venomhide hatchling looks at you expectantly, then begins to scrawl a pictogram into the dirt.\n\nThe hatchling's drawings seem to resemble various types of large insects, perhaps the gorishi silithids. The hatchling finishes his picture, then gestures at it with one short arm, snaps its jaws, and licks its lips.\n\nIt must want you to go to the Slithering Scar, in the center of the southern part of Un'Goro Crater, and gather silithid meat. When you have the meat, feed it to your hungry hatchling.", sourceObjective = "Your Venomhide Hatchling wants you to feed it 10 Silithid Meat.", progress = "The hatchling cocks its head and looks at you.", completion = "Your venomhide hatchling flashes you a toothy smile and then settles in for a nap.", sourceObjectiveStatus = "unverified-source-field" }
quests[13918] = { id = 13918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Titans' Terminal", description = "Now that we have the disc, a lot of our earlier finds are starting to make sense. Shortly after my arrival, Prospector Remtravel unearthed what he presumed to be a prehistoric toaster.\n\nIt's my belief that this slotted box is some sort of data reader. Unfortunately, it broke apart and washed away with the rest of our base camp when the tidal wave struck!\n\nIt can't have gone far, {name}. Pieces must be buried in the nearby sand. Here, use my trusty buried artifact detector to comb the beach for them.", sourceObjective = "Use Buried Artifact Detector on the beach near Remtravel's Excavation site to locate 5 Ancient Device Fragments. Combine them to create the Ancient Slotted Device.", progress = "Did you assemble all the pieces of the slotted device? We may need to remove Prospector Remtravel's sandwich from the ancient data interface.", completion = "Why yes, yes, this is it! See here, the slot is the exact dimensions of the ancient disc, just as I'd surmised. Here's your reward, {name} - you've earned it.\n\n\n\nAre you ready to meet history face to face? Let's see what the ancients have to say!", sourceObjectiveStatus = "unverified-source-field" }
quests[13919] = { id = 13919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trip to the Moonwell", description = "It didn't work.\n\n<A sorrowful and resigned expression upon his face, Pelturas removes the tear from the soup and gently washes it.>\n\nThe eruption of Thunder Peak must have affected it in some way. You must take the tear to the Moonwell of Purity, which still lies intact, protected by the goddess' power, at the southeast base of the volcano.\n\nThere, you will wash it in the sacred waters of Elune. What happens beyond that, I cannot say. I fear for my daughter's life. It is in your hands now, {name}.", sourceObjective = "Take the Tear of Elune and cleanse it in the waters of the Moonwell of Purity in Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[13920] = { id = 13920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before You Go...", description = "We have urgent need for good {class}s at Hellscream's Watch, {name}. But before you're dispatched, there remains something that needs doing here.\n\nMost of our perishable goods were lost at sea due mainly to Alliance attacks. We must stock enough food to carry out our Ashenvale campaign.\n\nJust east of here, you should find wildlife in abundance. Bring back the best meat you can find for our troops!", sourceObjective = "Bring 5 Venison Steaks to Commander Grimfang in Zoram'gar.", progress = "Yes, {race}?", completion = "These venison should make our soldiers' spirits rise for the coming battles. Here's something for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[13921] = { id = 13921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Who Would Be Forgiven", description = "<A voice from inside the moonwell flows over your mind, bringing you a perfect sense of peace.>\n\nYou seek to cure a child, but know that all things come at a cost. To the east lies Raynewood Tower. Standing outside the tower, next to my moonwell, is one who has fallen into corruption.\n\nAvrus Illwhisper seeks forgiveness and redemption, {name}. Will you help him to attain that which he desires and in so doing achieve your own goal?", sourceObjective = "Speak with Avrus Illwhisper at Raynewood Tower in Ashenvale.", completion = "<The satyr sneers, but when he realizes you are not here to chastise him, he changes his expression.>\n\nFinally, my redemption is at hand. I have waited long for this day and I think I know how to help you in turn.", sourceObjectiveStatus = "unverified-source-field" }
quests[13922] = { id = 13922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Hands of the Perverse", description = "My former clan, the Felmusk of Night Run, raided Fallen Sky Lake some time ago, stealing the moonstones that were unique to the area.\n\nThose moonstones are known to have great healing properties and surely can be used to cure the little girl that lies sick in Astranaar.\n\nNight Run rests up the road to the east that runs north. There are multiple paths that lead up into the hills on its eastern side, and it is there that you will find my unrepentant brethren. They will have what you seek.", sourceObjective = "Obtain 5 Fallen Moonstones.", progress = "Five moonstones are required to assure that the girl is healed.", completion = "You have all of the moonstones that are needed. And yet, it is said that a sacrifice of life is the only way to ensure the saving of another.\n\nI will ensure that no matter what, the moonstones will cure Relara.", sourceObjectiveStatus = "unverified-source-field" }
quests[13923] = { id = 13923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Hellscream's Watch", description = "Into the fray with you, {race}!\n\nHellscream's Watch is one of our most contentious fronts in Ashenvale. The experience should serve you well... assuming you survive.\n\nWhen you've made ready, speak with Andruk. I've arranged for him to transport you directly to your station.\n\nOnce you've arrived, seek out Captain Goggath. He will guide you further.\n\nBring pain and death to our enemies! For the Horde!", sourceObjective = "Speak to Captain Goggath at Hellscream's Watch.", completion = "You come here as a child, {race}.\n\nYou shall leave here a battle-hardened {class} of the Horde!\n\nThat, or a corpse....", sourceObjectiveStatus = "unverified-source-field" }
quests[13924] = { id = 13924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All's Well", description = "Thank you for saving me from a fate worse than death, {name}! For saving both the child and myself!\n\nWell, the child is almost saved. All you have to do is take the moonstones back west down the road to Astranaar. Hand them to Pelturas and he will know what to do.\n\nGo in peace, my friend. Elune be praised!", sourceObjective = "Deliver the Sanctified Moonstones to Pelturas Whitemoon at Astranaar in Ashenvale.", progress = "{name}, is that you? Have you returned with the cure for Relara?", completion = "Oh, {name}, you have saved my daughter! I know the power of the moonstones will give back my daughter her strength!\n\nI can never repay you fully for the aid you have given me, but... please, take this. Other than Relara, it is my most dear possession.", sourceObjectiveStatus = "unverified-source-field" }
quests[13925] = { id = 13925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ounce of Prevention", description = "Are you familiar with the Old Ones, {name}? Onu and I agree that the artifact you found in the lake can only be their work, and it's devouring Darkshore. Something is stirring up terrors we thought dead long ago. This is bigger than you or me, but my first concern is protecting the wildlife.\n\nHere, this sapling contains the life essence you gathered for me. I believe it can protect the local fauna. Test it out on a nearby un-consumed bear, stag, or moonstalker, and let me know what happens!", sourceObjective = "Test the Lifebringer Sapling on any nearby healthy Grizzled Thistle Bear, Whitetail Stag, or Moonstalker Matriarch/Sire.", progress = "The sapling you carry grows in power even as we speak. Life is regenerative, {name}. Did it work?", completion = "Interesting... It sounds like our cure will keep the wildlife safe, but you say you saw something else? Some kind of angry presence?\n\nThis is a good sign, {name}. Whatever is behind this isn't happy, and that means we're on to something.", sourceObjectiveStatus = "unverified-source-field" }
quests[13926] = { id = 13926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Orphan Roo Of The Oracles", description = "The orphans have been looking forward to the opportunity to meet friends like you, {name}. It's wonderful that you've agreed to take one into your care.\n\nTake this whistle.  With it, you will be able to call for the orphan you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  He will be excited to meet you and see the sights of Northrend with you.", sourceObjective = "Speak to Orphan Matron Aria, then use the Oracle Orphan Whistle to call the orphan you will be taking care of during Children's Week.", progress = "You taking care of us?", completion = "You take us away from puppy-men hatchlings? Good. We like you already. Mean puppy-men hatchlings took all our favorite toys away.", sourceObjectiveStatus = "unverified-source-field" }
quests[13927] = { id = 13927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Orphan Kekek Of The Wolvar", description = "The orphans have been looking forward to the opportunity to meet friends like you, {name}. It's wonderful that you've agreed to take one into your care.\n\nTake this whistle.  With it, you will be able to call for the orphan you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  He will be excited to meet you and see the sights of Northrend with you.", sourceObjective = "Speak to Orphan Matron Aria, then use the Wolvar Orphan Whistle to call the orphan you will be taking care of during Children's Week.", progress = "Orphan lady say Kekek go with you.", completion = "You take Kekek hunting? Good to get away from mean old orphan lady who doesn't let Kekek hunt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13928] = { id = 13928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover the Fallen", description = "I and my sentinels have been ordered by Keeper Ordanus to stay here and hold the tower. So far we've been able to repel the Horde, but now they're going around us to directly attack the retreat to the north.\n\nThe keeper sent out his dryads to defend the tree, but they do not seem to be much of a match for the vanguard of the Warsong orcs.\n\nI need you to go out there and recover as many laughing sister corpses as you can. Take them to Halannia inside the tree at the retreat. She will know what to do.", sourceObjective = "Recover 10 Laughing Sister's Corpses.", progress = "I'm amazed that you broke through the Horde lines and managed to get in here, {race}.", completion = "Thank you, {class}. We have our hands full defending the retreat, but when I can catch my breath, I'll see to it that these sisters are returned to life, the Goddess willing.\n\nYou've demonstrated your prowess... we can use your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[13929] = { id = 13929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Biggest Tree Ever!", description = "Before there was a big war and we left the village, we remember Soo-say telling us all about the biggest tree ever!\n\nSoo-say call it Grizzlemaw or something. Soo-say tell us it in the middle Grizzle Hills. No, wait, that not what Soo-say say. Soo-say say Grizzly Hills. Now we remember! Tree is big and right in middle of Grizzly Hills. Can't miss!\n\nYou take us there, oki? We see inside of giant tree? Soo-say tell us big bear men live in tree too. Maybe we see them.", sourceObjective = "Take your orphan, Roo, to visit Grizzlemaw. Make sure to call for him if he is not present when you enter the trunk of the great tree.", progress = "Can we see the big tree? Can we?", completion = "We never knew trees got that big! Nope. Maybe Great Ones had special plan for it?", sourceObjectiveStatus = "unverified-source-field" }
quests[13930] = { id = 13930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Of The Bear-Men", description = "High Shaman Rakjak always tell stories of mighty warriors, even ones far away. Sometimes he tell stories about giant bear-men fighting great battle for tree-city.\n\nMaybe you take Kekek there, see tree, see battle! High Shaman Rakjak tell Kekek that giant tree-city Grizzlemaw stand in the middle of Grizzly Hills.\n\nKekek never see a city before meeting orphan lady, but this city have no warriors, only men in purple dresses. Kekek want to see real warriors fight for real city.", sourceObjective = "Take your orphan, Kekek, to visit Grizzlemaw. Make sure to call for him if he is not present when you enter the trunk of the great tree.", progress = "Kekek want to visit bear-men tree. We go.", completion = "This is Kekek's kind of city. Bear-men fight for home just like Frenzyheart do. Orphan lady tell Kekek not to fight with other pups, but Kekek fight anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[13931] = { id = 13931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Year, Another Souvenir.", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", sourceObjective = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", progress = "What's happening hot stuff?  Got something for me?", completion = "What's this?  A stein voucher?  So you like drinking?  Great!  After I give you this stein, go have a few drinks!  Then a few more.  Maybe have a few more after that...  Then, now this is important, come see me.\n\nLook, I know you'll be back eventually.  If you want your Brewfest tokens redeemed you have to see me.\n\nAnyways, here's the stein, and remember to talk to me later.", sourceObjectiveStatus = "unverified-source-field" }
quests[13932] = { id = 13932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Year, Another Souvenir.", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", sourceObjective = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", progress = "What's happening hot stuff?  Got something for me?", completion = "Aww, it's just a stein voucher... Maybe you're just playing hard to get.  So here's this year's stein for you.\n\nBut I suspect I'll be seeing a lot more of you.  After all, if you want any Brewfest tokens redeemed, I'm your girl...\n\nOr maybe I'm his girl...  \n\nOooohhh... or his...", sourceObjectiveStatus = "unverified-source-field" }
quests[13933] = { id = 13933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bronze Dragonshrine", description = "Sometimes High-Oracle Soo-say tell stories about a shrine to dragon-things, not like great rain stone, but different. Soo-say tell us maybe we see ourselves there, but not like in a shiny. Soo-say mean we could see what we are like many years from now.\n\nYou take us there? We remember shrine to bronze dragon-things in place called Dragonblight. Soo-say say great rain stone show him shrine to northeast of Wyrmrest Temple, or northwest of place dryskins call Wintergarde Keep. We go?", sourceObjective = "Take your orphan, Roo, to visit the Bronze Dragonshrine. Make sure to call for him if he is not present when you get there.", progress = "We visit shrine to dragon-things?", completion = "We very glad you brought us here, {name}. We always worried what would happen to us when the orphan matron found us in Sholazar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13934] = { id = 13934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bronze Dragonshrine", description = "When Kekek was a pup, he sometimes heard elders talking about a far-off shrine. Sometimes they say that bronze dragon-things there know all about future.\n\nKekek tell you he be great warrior, now we go see. Bronze dragon-thing shrine somewhere in Dragonblight, northeast of dragon-thing temple called Wyrmrest, also northwest of man-town called Wintergarde.\n\nWe go there, see future. Prove orphan-lady wrong about Kekek. Kekek warrior, not bully.", sourceObjective = "Take your orphan, Kekek, to visit the Bronze Dragonshrine. Make sure to call for him if he is not present when you get there.", progress = "Kekek want to visit dragonshrine.", completion = "See? Kekek never get tired of saying, \"Kekek tell you so.\"\n\nMaybe now you believe other things Kekek tell you, like how sky is green.", sourceObjectiveStatus = "unverified-source-field" }
quests[13935] = { id = 13935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Tree!", description = "We have been using the power of the Forest Heart to defend the tree from the Horde, but its power is not without limit. We must use it to take the fight to them!\n\nShadumbra, the great cat of the forest, prowls nearby. It is from her that we shall draw our inspiration. You will become one with the shade of Shadumbra. You will take the essence of the panther into you and lay waste to those who dare attack the might of Ashenvale!", sourceObjective = "Speak with Halannia to summon the Shade of Shadumbra and use its power to destroy any 50 Warsong enemies at Raynewood Retreat.", completion = "A brutal display, but one fitting for the enemies of Ashenvale. The Horde dares to think that they can take our beloved forest away from us.\n\nThey are fatally mistaken!\n\nYou have saved Raynewood from destruction, {name}. Surely we can find a reward suitable for our champion?", sourceObjectiveStatus = "unverified-source-field" }
quests[13936] = { id = 13936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tweedle's Dumb", description = "Delays, delays, delays! I'm at wit's end!\n\nI was told that this goblin was brilliant - that he'd come up with gadgets sure to shock the enemy into submission. So far he's produced nothing but empty promises. If he comes up empty-handed again, I'm going to toss him off the cliff!\n\nYou go and speak to him, {class}. Let him know that my fuse is running short!", sourceObjective = "Captain Goggath wants you to speak with Tweedle at Hellscream's Watch.", completion = "Let me tell ya somethin' {class}!\n\nThe bossman simply doesn't appreciate the art and craftsmanship that goes into making fine explosives.", sourceObjectiveStatus = "unverified-source-field" }
quests[13937] = { id = 13937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trip To The Wonderworks", description = "We have time for one more stop? We heard Dalaran has toy store, but we never get to go there. Orphan mistress says too many orphans would crowd the store. Maybe we can go, just us?\n\nWe can have a small paper zeppelin? We think they have those at Wonderworks in Dalaran. We always wanted to play with one. Maybe you throw one to us?", sourceObjective = "Purchase a Small Paper Zeppelin at the Wonderworks and then throw it to your orphan, Roo.", progress = "We go to the Wonderworks?", completion = "That was fun! We like toy store. Maybe orphan matron take us sometimes. We ask. Maybe you tell her too?", sourceObjectiveStatus = "unverified-source-field" }
quests[13938] = { id = 13938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit To The Wonderworks", description = "You take Kekek one more place? Orphan lady say Dalaran have toy store called Wonderworks, but Kekek never seen it. She say that if one orphan go, she have to take everyone. Maybe you take Kekek?\n\nKekek seen other children playing with small paper zeppelin? Kekek hear those come from Wonderworks. Maybe you get one and throw it around with Kekek?", sourceObjective = "Purchase a Small Paper Zeppelin at The Wonderworks and then throw it to your orphan, Kekek.", progress = "This toy store yet?", completion = "Kekek like playing with paper zeppelin. Not as good as hunting, but give something to do when bored at orphanage.", sourceObjectiveStatus = "unverified-source-field" }
quests[13940] = { id = 13940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leaving the Dream", description = "Hold on tight, {name}.  The journey back to the waking world can be a little rough on unprepared minds and bodies.", sourceObjective = "Speak to Malfurion at the Eye of the Vortex in Darkshore.", completion = "You're just in time, {name}.  I don't know how much longer we can hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13942] = { id = 13942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set Us Up the Bomb", description = "I'm definitely on to something here!\n\nI have enough volatile elements salvaged from our arsenal to make the explosives Goggath wants, but I need to stabilize it and pack it into bombs.\n\nWhat I need is some clay - and not just any clay... moon-kissed clay.\n\nIt's only found on the northern banks of Astranaar Lake, and it possesses the qualities I need to bring out the full potential of my discovery!", sourceObjective = "Tweedle at Hellscream's Watch wants you to collect 10 samples of Moon-Kissed Clay.", progress = "Let's see what you've brought me, {race}.", completion = "This is PERFECT!\n\nOh, just wait 'til you see what I can do with this....", sourceObjectiveStatus = "unverified-source-field" }
quests[13943] = { id = 13943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breathing Room", description = "Our forces are not ready to assault Astranaar just yet, {class}. They know we're coming, though, and they're not content to sit and wait for us. At the base of this cliff they've created a camp from which they launch bothersome attacks by the light of the moon.\n\nBefore these skirmishes bolster their confidence any further, I want you to visit them with the wrath of the Horde! Return to me when the elves have been humbled a bit.", sourceObjective = "Captain Goggath wants you to kill 10 Astranaar Skirmishers and 3 Astranaar Officers.", progress = "Well, {race}, have you taught the elves a little humility?", completion = "Well done, {race}. But there is much that remains to be done here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13944] = { id = 13944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Stature, Short Fuse", description = "<Tweedle gesticulates emphatically.>\n\nI've done it! This should satisfy even Goggath!\n\nWe just need a test that will sufficiently show off our efforts... ahh, the wagon!\n\nThe bossman's wanted that rotted out piece of junk hauled off for days. Use my explosives to get rid of it, then see what the captain has to say!", sourceObjective = "Use the Improvised Explosive Stick on the Broken-down Wagon at Hellscream's Watch.", progress = "What have you done, {race}?", completion = "So, Tweedle found a way to get those explosives working, eh?\n\nIt's about time...", sourceObjectiveStatus = "unverified-source-field" }
quests[13945] = { id = 13945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resident Danger", description = "The Gnarlpine aggression is limiting our options. None of our kind are eager to bring blade and arrow against creatures that were once our friends, but I grow fearful that they are going to set their sights on Dolanaar soon.\n\nThe biggest concern to me are the furbolg in Ban'ethil Hollow and Ban'ethil Barrow Dens. I need you to travel to the west, make your way into the Barrow Den, and kill as many of the Gnarlpine as you can. We probably won't have many more chances to limit their strength - be swift.", sourceObjective = "Kill 20 Gnarlpine Furbolg in and around Ban'ethil Barrow Den.", completion = "Impressive. I hope my huntress carried her weight.\n\nIf we continue with this fervor, we may yet still free Teldrassil from the corruption that Alexstrasza herself could not burn out.", sourceObjectiveStatus = "unverified-source-field" }
quests[13946] = { id = 13946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature's Reprisal", description = "I'm glad you were willing to atone for your mistake - it speaks a great deal about your character.\n\nI have another task for you. I have gathered some ireroot seeds. They are somewhat like fel cones, but quite a bit more potent. Nature often responds very negatively to demons, and these ireroot seeds prompt a very concentrated form of that reprisal.\n\nTo our north, in Fel Rock, there are grellkin that are far beyond redemption. Use the ireroot seeds to route them before they become a more serious threat.", sourceObjective = "Use ireroot seeds to kill 12 grellkin in Fel Rock.", completion = "Good. I know this probably wasn't very pleasant work, but we greatly appreciate it.\n\nI fear for our dear Teldrassil... it seems it is becoming more corrupt by the day, and our ignorance to the cause is plaguing me greatly.", sourceObjectiveStatus = "unverified-source-field" }
quests[13947] = { id = 13947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blastranaar!", description = "So, Tweedle finally came through on those explosives, eh?\n\nThey couldn't have come at a better time. The elves of Astranaar are preparing to make a devastating assault on our camp as we speak.\n\nDrop our new weapon on them from the skies! The destruction of Astranaar will be a dagger in the heart of night elves everywhere!\n\nSpeak with Thraka when you're ready to begin the assault.\n\nAim true, {class}.", sourceObjective = "Captain Goggath wants you to use Tweedle's Improvised Explosives to kill 20 Astranaar Sentinels and destroy 10 Astranaar Throwers.", progress = "Astranaar is burning!\n\nFor the Horde!", completion = "Your deeds today shall live long in the Horde's glorious history.\n\nYour efforts have dealt a devastating blow to the enemy!", sourceObjectiveStatus = "unverified-source-field" }
quests[13948] = { id = 13948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stepping Up Surveillance", description = "The cultists appear to be digging out the remains of a being known as Soggoth the Slitherer.\n\nPerhaps their superiors on the rafters above have more information.", sourceObjective = "Sneak into the Master's Glaive using the Panther Figurine and spy on the Twilight's Hammer leaders on the platform above.", completion = "This is dire news, {name}.  If you are correct, then we'd best act swiftly and decisively.\n\nWe cannot allow this \"Soggoth\" to be brought back to life.", sourceObjectiveStatus = "unverified-source-field" }
quests[13949] = { id = 13949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crossroads Caravan Pickup", description = "<Halga grins disarmingly, holding up an enormous firearm.>\n\nHave you ever used one of these, {name}? It's a beast. Hell with a handgrip. Too heavy to use on foot, but perfect when riding at the head of a caravan. I call it my 'street sweeper.'\n\nWe need to get those supplies you've collected to the Crossroads, and I expect trouble. I'd like for you to ride shotgun. Literally! Say the word when you're ready and I'll put you at the head of our next caravan.", sourceObjective = "Speak with Halga Bloodeye at Far Watch Post to escort the next Crossroads Caravan to Grol'dom Farm.", progress = "Mok'ra, stranger. Are you here from Far Watch?", completion = "You're a sight, {race}. That's the first caravan to make it through this week!", sourceObjectiveStatus = "unverified-source-field" }
quests[13950] = { id = 13950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playmates!", description = "Orphanage gets real lonely, you know? Sometimes we want to go places, meet new friends.\n\nMaybe you can take us somewheres with other hatchlings? We heard about a place called Winterfin Retreat, in the big Borean Tundra. We think it's way in the northwest, near the edge of the Coldarra-island.\n\nThe orphan lady say someone brave save a bunch of hatchlings there. We think they lonely, too. We think they need friends. You take us there?", sourceObjective = "Take your orphan, Roo, to visit Winterfin Retreat. Make sure to call for him if he is not present when you get there.", progress = "You take us to Winterfin Retreat? Meet new friends maybe?", completion = "That was fun! We go again sometime? We can't wait to see our new friend again!", sourceObjectiveStatus = "unverified-source-field" }
quests[13951] = { id = 13951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playmates!", description = "Kekek think there not enough other pups living with orphan-lady. Maybe we go visit some others?\n\nKekek know a tribe that lives in Dragonblight, at place called Snowfall Glade. You know? Snowfall Glade north of walrus-men town of Mo'aki Harbor and south of Ruby Dragonshrine.\n\n<Kekek scowls at the mention of the tuskarr.>\n\nYou take Kekek there, to some of the villages there. Maybe we meet new wolvar, show them how fierce Frenzyheart are!", sourceObjective = "Take your orphan, Kekek, to visit Snowfall Glade. Make sure to call for him if he is not present when you get there.", completion = "Kekek like new Snowfall friends, maybe come back and go hunting together sometime. Maybe we go tip over walrus-men when they sleeping.", sourceObjectiveStatus = "unverified-source-field" }
quests[13952] = { id = 13952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", sourceObjective = "Acquire some Bread of the Dead and give it to the Cheerful Human Spirit in Stormwind's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", sourceObjectiveStatus = "unverified-source-field" }
quests[13953] = { id = 13953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga In Our Midst", description = "The creature appears to have had its skull broken in a fight with Aros.  It looks like what you've heard described as a naga before.\n\nIt is said that despite their monstrous features, naga are night elves warped by the arcane magic of Queen Azshara.\n\nIt seems they've decided to stop you from obtaining the horn of the ancients.", sourceObjective = "Return to Balren of the Claw at the Grove of the Ancients in Darkshore.", completion = "The naga are in league with the Twilight's Hammer?  Just what we needed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13954] = { id = 13954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragon Queen", description = "One of High-Oracle Soo-say's stories says Great Ones made all the dragons and a queen for the dragons, too. We want to see her! Would you take us to the top of Wyrmrest Temple? We remember Soo-say telling us the temple-thing was in the middle of Dragonblight.\n\nWe really want to meet dragon queen. She must be so big and pretty. Maybe she help us find new parents.\n\nYou take us?", sourceObjective = "Take your orphan, Roo, to visit Alexstrasza the Life-Binder at the top of Wyrmrest Temple. Make sure to call for him if he is not present when you get there.", completion = "Do you think she ever saw an oracle before? We might be the first one ever to meet her! We thinks she liked us, but we're not sure. She doesn't talk a lot. Nope. But that was fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[13955] = { id = 13955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragon Queen", description = "Kekek always liked dragons. Always wanted to be one, but orphan-lady said no. But she did say maybe you take Kekek to meet dragon queen.\n\nKekek think orphan-lady have good idea for once. You take Kekek to Wyrmrest Temple in the middle of Dragonblight? Fly all the way to top to meet dragon queen. She must be really big, to be queen of all dragons. Kekek can't wait to see!", sourceObjective = "Take your orphan, Kekek, to visit Alexstrasza the Life-Binder at the top of Wyrmrest Temple. Make sure to call for him if he is not present when you get there.", completion = "Queen not what Kekek expected, but Kekek understand why. Queen's visitors get crushed if she was always big dragon! Still want to see someday.", sourceObjectiveStatus = "unverified-source-field" }
quests[13956] = { id = 13956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meeting a Great One", description = "High-Oracle Soo-say always tell us about how Great Ones built shrines and we give them shinies, but he never see Great Ones. No one see Great Ones, but maybe you know how to find one?\n\nSoo-say told us the Great Ones made a waygate and put it in the center of the southern part of Sholazar. Soo-say not say where it goes, but maybe it take us to a Great One! Take us through that waygate and let's find out, {name}.", sourceObjective = "Take your orphan, Roo, to visit the Etymidian at the Shaper's Terrace. Make sure to call for him if he is not present when you get there.", completion = "We got to meet a Great One! Too bad it was during his nap time, but we understand. We like naps, too! Maybe we learn naps from Great Ones like we learn about shrines and shinies!\n\nCan we come back and visit the Great One again when not sleeping?", sourceObjectiveStatus = "unverified-source-field" }
quests[13957] = { id = 13957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mighty Hemet Nesingwary", description = "Know who Kekek always wanted to meet? Hemet Nesingwary.\n\nMaybe you take Kekek to see him? Elder Harkek tell us all about him. He come to Sholazar to hunt biggest creatures anywhere! Even Frenzyheart elders respect Hemet Nesingwary as great hunter.\n\nElder Harkek tell Kekek that Nesingwary Base Camp in the middle of west side of Sholazar, right on river called Seabreach Flow. We go visit and learn how to hunt like Hemet?", sourceObjective = "Take your orphan, Kekek, to visit Hemet Nesingwary at the Nesingwary Base Camp. Make sure to call for him if he is not present when you get there.", progress = "Can't wait to meet Hemet Nesingwary.", completion = "You help Kekek learn him a book? Then, Kekek hunt with Hemet Nesingwary!", sourceObjectiveStatus = "unverified-source-field" }
quests[13958] = { id = 13958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Condition Critical!", description = "We have the enemy on their heels. Victory is within sight!\n\nIt is not yet time to celebrate though, {class}. There remains much to be done before the Horde can lay claim to Ashenvale.\n\nAt Raynewood Retreat to the east a battle has been joined. Reports indicate many Horde wounded.\n\nTake these medical supplies there and give them to Thagg. Tell him of our assault on Astranaar. It may help to bolster morale.", sourceObjective = "Goggath wants you to bring the Battle Triage Kit to Thagg at Raynewood Retreat.\n\nProvided item:", completion = "<Thagg listens intently as you recount your assault on Astranaar.>\n\nThis is good news indeed, {race}. But right now, we need more than just good news here.\n\nThese triage kits will be put to good use!", sourceObjectiveStatus = "unverified-source-field" }
quests[13959] = { id = 13959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back To The Orphanage", description = "We had the best time with you, {name}. We wish you could be our <daddy/mama> now, but you have to take us back to Orphan Matron Aria in Dalaran.\n\nMaybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One!\n\nWe going to miss you, {name}. We promise to write letter sometime, oki?", sourceObjective = "Return your ward to the Dalaran orphanage by handing in the Oracle Orphan Whistle to Orphan Matron Aria in Dalaran.", progress = "Do we have to go back? We want to stay with you.", completion = "It sounds like little Roo had a great time this week. I know he was getting awfully lonely in the orphanage and was eager to make some new friends. Thank you so much for agreeing to look after him.", sourceObjectiveStatus = "unverified-source-field" }
quests[13960] = { id = 13960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back To The Orphanage", description = "Know what? You not so bad after all, {name}. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do.\n\nYou, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes.\n\nKekek gotta go back to orphan-lady Aria now, back in purple human city.", sourceObjective = "Return your ward to the Dalaran orphanage by handing in the Wolvar Orphan Whistle to Orphan Matron Aria in Dalaran.", progress = "Kekek not want to go. Kekek want to see more of Northrend with {name}.", completion = "Thank you for agreeing to care for Kekek this week. I know he can be a handful, but I think that with more individual attention and a few more friends, he'll do a lot better. No doubt he's going to be telling stories of his adventures with you for weeks.", sourceObjectiveStatus = "unverified-source-field" }
quests[13961] = { id = 13961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag it Out of Them", description = "It is our instinct to simply lash out at our attackers, but wisdom dictates another path. We should interrogate one of these quilboar invaders and learn all we can. Take this net, {name}, and ensnare a quilboar pillager attacking our farm just west of here. Club the beast unconscious and bring him to me.", sourceObjective = "Use the Grol'dom Net to ensnare a Razormane Pillager and drag it back to Togrik at Grol'dom Farm.", progress = "Don't be too harsh with our captive, he will still need his head attached to answer our questions.", completion = "Oh my. We want to question this quilboar, not tenderize him!", sourceObjectiveStatus = "unverified-source-field" }
quests[13962] = { id = 13962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalemate", description = "The triage kits will help us keep up the fight, but we are at a stalemate.\n\nThe dryads die easy enough, but their leader is resurrecting them soon after they fall. We face an endless stream of the vermin!\n\nKeeper Ordanus hides in that mutated tree. Our efforts to fight our way to him have been in vain. Perhaps you could work your way to him while we contend with his dryads...\n\nSurely, this is child's play for someone who has conquered Astranaar. No?", sourceObjective = "Thagg at Raynewood Retreat wants you to kill Keeper Ordanus.", progress = "Well, {race}? Is Ordanus defeated?", completion = "Very well, {name}.\n\nYou have succeeded where I could not. You have earned my respect.", sourceObjectiveStatus = "unverified-source-field" }
quests[13963] = { id = 13963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Hook Or By Crook", description = "I suppose he'll come around with some cold water to the face. What do you think he'll tell us?\n\nI'll secure him inside our livestock pen behind me here. I don't think he'll stay conscious long. Find out what you can about why the quilboar are attacking our farms! I'll leave the interrogation methods up to your better judgment.", sourceObjective = "Question the nearby Razormane prisoner. If he's not there or unconscious, Togrik can revive him for you.", progress = "Well, did he squeal?", completion = "Very interesting - our brute here seems both enthralled and terrified of the one they call \"Tortusk.\" A powerful leader can inspire his people to acts of greatness or atrocity... but we orcs would know that more than others.\n\nWe should turn our attention to this Tortusk problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[13964] = { id = 13964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Spire", description = "We've lost Silverwind Refuge! All that I know is that there was a surprise attack by the Horde and that they somehow turned Mystral Lake's elemental guardians against us.\n\nThe survivors have fallen back to Stardust Spire. {name}, they need your help.\n\nHead south by southeast. You'll find the spire at the mouth of the Talondeep Pass, which leads into the Stonetalon Mountains. I'm sure that you'll find Sentinel Velene Starstrike helping with the counter-offensive there.", sourceObjective = "Speak with Sentinel Velene Starstrike at Stardust Spire.", completion = "Good to finally meet you, {name}. I've heard all about what you've been up to and let me just say that I'm impressed!\n\nThink you can lend us your expertise?", sourceObjectiveStatus = "unverified-source-field" }
quests[13965] = { id = 13965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Check in on the Edunes", description = "{name}, if you have a moment to spare, I would enlist your aid in a simple matter.\n\nI have not heard from my friends, the Edunes, in some time. I was wondering if you could swing west and check in on them?\n\nYou have my thanks. Their cottage sits on a small plot of land just to the west of the Shrine of Aessina.", sourceObjective = "Speak with Benjari Edune at the House of Edune in Ashenvale.", completion = "You say that Faldreas sent you?  Good man.\n\nAs it happens, we could use your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[13966] = { id = 13966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", sourceObjective = "A small tag on this present reads:\n\nHappy holidays, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13967] = { id = 13967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the... Herd?", description = "The furbolg are more numerous than we expected in these southern regions. They have also been far more aggressive here than we would like.\n\nWith our resources divided between hunting down elves and harvesting much-needed lumber, that leaves you to help me put an end to our furbolg distraction.\n\nI have research to conduct here. In the meantime, I need you to take a more hands-on approach. Bring me the ears of nearby furbolg as proof to Tarkan that the problem is being dealt with.", sourceObjective = "Senani Thunderheart at Silverwind Retreat wants you to collect 15 Furbolg Ears from Foulweald Totemics and Foulweald Ursas.", progress = "Well, {name}.\n\nIs it done?", completion = "Good work, {race}.\n\nThis should keep them licking their wounds for a time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13968] = { id = 13968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tortusk Takedown", description = "In the wake of the chaos down south, this \"Tortusk\" brute seems to have rallied all of the Razormane refugees to his banner. Under his leadership, he's turned them into little more than brigands. There's no negotiating with his type; Tortusk must be destroyed.\n\nIf our prisoner is to be believed, you'll find Tortusk southeast of here at a place called Thorn Hill. Search the bluffs where he has a commanding view of the road. Kill him, {name}, and the immediate threat should cease.", sourceObjective = "Kill the Razormane leader, Tortusk.", completion = "Ah, so Tortusk behaved as I expected? Went right for your throat? It is good that he's dead.\n\nThe Razormane quilboar have been separated from their leadership in the southern Barrens, no doubt allowing an animal like him to come to power. Perhaps without his influence we can start a dialogue with the survivors... Although hotter heads may prevail.", sourceObjectiveStatus = "unverified-source-field" }
quests[13969] = { id = 13969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grol'dom's Missing Kodo", description = "Friend, if you are traveling south to Thorn Hill, I was wondering if you could locate one of our missing kodos? Not every caravan has made it up the pass from Far Watch Post. Those Razormane brutes hijacked a pack animal yesterday morning. It may not still be alive, but if it is, we cannot afford to lose more of our livestock.", sourceObjective = "Find a missing Grol'dom Kodo somewhere within Thorn Hill in Northern Barrens.", completion = "This poor battered kodo looks to be on the verge of death, but is still breathing. The Razormane haven't even plundered its cargo yet. If it can be revived, you may be able to save the entire shipment.", sourceObjectiveStatus = "unverified-source-field" }
quests[13970] = { id = 13970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animal Services", description = "Kodos are resilient creatures. With some food, the big guy may come around.\n\nThe Razormane have stolen plenty of grain from previous caravans. You can gather up stolen grain from the nearby camps.", sourceObjective = "Gather 5 sacks of Stolen Grain from the Razormane camps on Thorn Hill.", progress = "The creature doesn't lift its head, but looks at you imploringly with large, watery eyes.", completion = "The Kodo is voracious! You might as well be pouring those sacks of grain into a hole!\n\nAlready the animal is beginning to perk up.", sourceObjectiveStatus = "unverified-source-field" }
quests[13971] = { id = 13971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kodo's Return", description = "The great beast rises slowly to its feet, the loose Barrens soil spilling from its revitalized limbs. Instinctively it trudges back toward its home at Grol'dom Farm.\n\nYou'll want to check in with Kranal Fiss to make sure the kodo made it.", sourceObjective = "Speak with Kranal Fiss at Grol'dom Farm to ensure that his missing kodo arrived safely.", completion = "So that was your handiwork, {race}? Yes, the missing Kodo arrived just minutes ago. It will take many nights to nurse the poor beast's wounds, but thanks to you it's alive. And you saved a whole shipment!\n\nPlease, take your pick of the gear that the kodo was carrying.", sourceObjectiveStatus = "unverified-source-field" }
quests[13973] = { id = 13973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grol'dom Militia", description = "They came out of nowhere, {class}! Quilboar from horizon to horizon. Spines and snouts and teeth. We fell back to the farm but they kept on coming.\n\nOur best defenders have fallen in the field, and we've no sign of Farmer Ralton. I need you to go on the offensive for me! Hold these swine at bay while I defend the wounded until help arrives.", sourceObjective = "Slay 6 Razormane Pillagers.", progress = "I can see smoke from the neighboring building - what's going on out there?", completion = "I see you've left a string of corpses in your wake, {race}. I couldn't have done better. The livestock may be lost, but the land remains ours - thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[13974] = { id = 13974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tweedle's Tiny Parcel", description = "Wahoo!!\n\nLook at 'em burn! It's revolutionary! A real breakthrough in explosive technology - which, of course, is the only kind that matters....\n\nI'm gunna be the envy of every goblin south of Northrend!\n\nBelieve it or not, I've actually refined the formula to be even more potent!\n\nHere. Take a sample of this stuff southeast to Silverwind Refuge. Maybe my cousin Flooz can use it to help the Horde capture that objective.", sourceObjective = "Tweedle wants you to take Tweedle's Tiny Parcel to Flooz at Silverwind Refuge.\n\nProvided item:", completion = "Well, look at this! Little Tweedle has really come through this time. This stuff blew up Astranaar, you say?\n\nAs you can see, we don't need any help taking over Silverwind Refuge, but Tweedle always did think small.\n\nIf this stuff's really as good as you say, there's no limit to what we might do....", sourceObjectiveStatus = "unverified-source-field" }
quests[13975] = { id = 13975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crossroads Caravan Delivery", description = "<Rocco hands you a familiar-looking shotgun.>\n\nI took the liberty of cleaning up Halga's artillery for you. I'm sure I don't need to warn you about the kickback. Just ask me when you're ready to mount up for the Crossroads! Thork is waiting for you there. Be sure not to give him any lip.\n\nDon't stop for nothing, {name}, and if someone gets too close, just give 'em a thump with the butt-end of your gun. Do us proud!", sourceObjective = "Talk to Rocco Whipshank at Grol'dom Farm and escort his caravan all the way to the Crossroads.", progress = "Was that you I saw waving a gun around from the back of my last caravan?", completion = "It's about time we got some supplies through here. It's bad enough to be severed from Mulgore, but this city would fall apart if we lost our trade with Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13976] = { id = 13976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Friends of the Forest", description = "Care to make a quick trip to the south? I've three friends that I haven't heard from in a while. With these strange tentacles popping out of the ground to the north, and all of the demonic activity, I don't dare leave my family.\n\nBolyun set up his camp in the southwest corner of the forest, just to the northwest of that damnable Fire Scar Shrine. Alenndaar and Harlown joined him, so they should all be okay, but you never know.\n\nThanks, {name}.", sourceObjective = "Speak with Bolyun at Bolyun's Camp in Ashenvale.", completion = "{class}, you must be wary! Kaliva, the foul demoness who has chained us is nearby!", sourceObjectiveStatus = "unverified-source-field" }
quests[13977] = { id = 13977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mass Production", description = "Wahoo!! Did you SEE that?!\n\nWe need to get this into production right away!\n\nHere. Take the rest of the stuff to Jinx. You'll find him setting up our new facility just west of here.", sourceObjective = "Flooz wants you to take Tweedle's Pow-Pow Powder to Jinx at The Skunkworks.", progress = "Whatcha got there, boss?", completion = "<Jinx examines the powder carefully for a moment.>\n\nHmmm.\n\nIt'll take a little time. But yes, we can put this into a bomb....", sourceObjectiveStatus = "unverified-source-field" }
quests[13979] = { id = 13979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Goblin Braintrust", description = "If we could just stop the damned bombing from the goblins' creations we'd be able to launch a counter-offensive to take back Silverwind Refuge!\n\nIt's been my experience that goblins are either lazy and unproductive, or too productive and end up killing themselves with their own explosives. Unfortunately for us, they're being motivated by the brilliant Chief Bombgineer Sploder.\n\nGet up to the Skunkworks on the west side of the refuge and don't come back until you have the Chief Bombgineer's head!", sourceObjective = "Obtain Sploder's Head.", progress = "Did you shut that disgusting, wart-ridden goblin up for good?", completion = "That's better. Without him, their technicians are sure to fall back to their normal laziness, which should result in fewer bombs and more accidents.", sourceObjectiveStatus = "unverified-source-field" }
quests[13980] = { id = 13980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They're Out There!", description = "They're out there, {class}. And they're on to us.\n\nSome of my men have begun turning up dead. Elf attacks, no question about it.\n\nMy guess is that your work at Astranaar has them desperate to stop our progress here. A last ditch effort to escape defeat!\n\nTake these goggles. They'll help you see even the sneakiest of the elves. Keep them off my back while we finish weaponizing your explosives.", sourceObjective = "Jinx at The Skunkworks wants you to kill 12 Ashenvale Assassins.", completion = "Nice work, friend.\n\nYour skills have bought us the time we needed to prepare the bomb. It's almost complete!", sourceObjectiveStatus = "unverified-source-field" }
quests[13981] = { id = 13981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Set Them Up The Bomb!", description = "This is clearly the biggest explosive that you've ever laid eyes upon. What in the world could the goblins be thinking about bombing with such a monstrosity?\n\nTo your eye the thing looks like it's almost complete. The goblins appear to have built it well -- it looks as if it's impervious to any damage that you could do to it, and certainly too big for you to carry out of here.\n\nYou'd better report The Bomb to Huntress Jalin at Stardust Spire to the southwest!", sourceObjective = "Report the existence of The Bomb to Huntress Jalin at Stardust Spire in Ashenvale.", completion = "They what? IT'S HOW BIG?!!!\n\nI have a very bad feeling about this, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13982] = { id = 13982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In a Bind", description = "{name}, you must be cautious. Kaliva is still about and when she captured us, she specifically mentioned your name.\n\nOnly her heart can free us from these chains, but I think it's all a trap for you!", sourceObjective = "Obtain Kaliva's Heart.", progress = "If we are to be free, we must have Kaliva's heart.", completion = "Disgusting, I know, but if we three are to be free of Kaliva's chains, it is not enough that she is dead.\n\nWe must eat of her fel heart!", sourceObjectiveStatus = "unverified-source-field" }
quests[13983] = { id = 13983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building Your Own Coffin", description = "Once it's complete, we're going to need to get this bomb down to Saurboz.\n\nAnd by 'we', I mean 'you'.\n\nWith so many of the enemy prowling about, I'll need to create something special if you're to have any chance of success.\n\nI can modify one of these busted shredders, but I'll need a few parts. You should have no trouble finding them in the woods to the west.\n\nRound them up while I finish work on the bomb.", sourceObjective = "Foreman Jinx wants you to collect 3 Bronze Cogs, 3 pieces of Copper Plating, and 5 Locking Bolts.", progress = "You got those parts I need, friend?", completion = "This looks right, {class}.\n\nI should have your shredder put together in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13985] = { id = 13985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Shrine", description = "An end must be put to the Burning Legion's evil!\n\n{name}, you have defeated one of their most powerful, but there are still multitudes of demons infesting the woods to the east in Fire Scar Shrine.\n\nAs a friend of the forest, will you slay these foul creatures and then warn Big Baobob, the great ancient of war at the Shrine of Aessina to the northeast?", sourceObjective = "Slay any 12 demons at Fire Scar Shrine.", completion = "A fine job, my little {race} friend. But as you can see, I am a little busy here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13986] = { id = 13986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Injured Colleague", description = "The fight's been hard up here, {class}, as I'm sure you know. We're holding out, but not everyone has gone unscathed.\n\nA warrior in our band, Aponi Brightmane, was taken ill by an infected wound in her arm. She's been taken back to Thunder Bluff for recuperation. It seems she left her shield here at the front in the confusion, however - could you take it to her, along with our well-wishes? Her smile is missed around here.\n\nYou can find her on Elder Rise on the Bluff.", sourceObjective = "Take the Battered Tribal Shield to Aponi Brightmane on Elder Rise within Thunder Bluff.", progress = "Oh! Hello there. I don't think we've met; is there something I can do for you?", completion = "Oh, my shield! I won't be using it anytime soon, but thank you. I hate that I'm sitting here useless when I could be helping on the front, but fighting with my arm like this won't help anyone.\n\nTake care out there, won't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[13987] = { id = 13987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Stand", description = "{name}, I desperately need your help! I cannot hold out forever against this demonic onslaught. If I fall, Astranaar is next!\n\nPlease help me!", sourceObjective = "Slay 30 Demonic Invaders.", completion = "You've saved us all, {name}! I have the power to finish off these final few.\n\nNo longer will the forest have to fear the Burning Legion!", sourceObjectiveStatus = "unverified-source-field" }
quests[13988] = { id = 13988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Growing Problem", description = "An explosion of life from barren soil... My companion Jerrik has described similar events happening elsewhere in the Barrens. I shall have to see this for myself, but I cannot abandon my post.\n\nHere, {name}, I will loan you my 'eyes.' My eagle companion here has served me since I was named. Please accompany him to Thunderhead Summit, where Jerrik awaits, and we will investigate.\n\nTo get to the peak, follow the road east out of the Crossroads. Turn south when you reach a large stone scrawled with paintings.", sourceObjective = "Bring Tonga's Eyes to Thunderhead Summit southwest of Ratchet.", progress = "Tonga knows these lands better than any of us, and I believe it physically hurt him to see it torn asunder.", completion = "I am glad Tonga was able to witness the overgrowth firsthand - words can't convey the scope of the damage. Did you bring his totem? I will return it to him when I am finished here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13989] = { id = 13989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Foulweald", description = "I care little for who you are, {race}. What I do care about is the salvation of the furbolg.\n\nTake this Bloodtooth tribe banner a short ways northeast into Greenpaw Village and place it upon their totem mound. They will consider this an act of aggression and try to destroy the banner. Hold your ground until their chief, Murgut, appears to save face for the tribe, then kill the traitor!\n\nGovern your strength wisely, friend, you're in for a long fight.", sourceObjective = "Place the Bloodtooth Banner on the Foulweald Totem Mound. Do not let the furbolgs destroy the banner before their chief arrives. Defeat Chief Murgut.", completion = "Good. Murgut sold his own tribe out to the Horde, allying with them when they took your precious Silverwind Refuge in order to 'save' his people.\n\nHe sold them into slavery, or worse. And now he has gotten what he deserved!\n\nLet us speak now of a different traitor, one whom I believe has something that will make that rod of yours even more powerful.", sourceObjectiveStatus = "unverified-source-field" }
quests[13991] = { id = 13991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purloined Payroll", description = "Well, {name}. I admit there's a place for you in my beloved Horde. You've shown me strength, cunning, initiative ... Even Thork recently mentioned you by name, and neither of us are easily impressed. Well done.\n\nNow it's time to start pulling your weight. This week's payroll for the Crossroads guards has gone missing. Gazrog in Ratchet is heading up the investigation. Talk to him!\n\nSimply follow the road East of here to the coast.", sourceObjective = "Speak to Gazrog near the entrance to Ratchet.", completion = "I was hoping for a squad of grunts... but if you earned Sergra's respect, I suppose you'll be more than enough. Let me explain what's happening here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13992] = { id = 13992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Diversion", description = "I was sent here to scout out the centaur activity. I've been trackin' their every movement for days! It's time for me ta sneak out, but they've got this oasis surrounded.\n\nYou look like a dangerous one. Can you make a lot of noise for me? Stir 'em up! Start killin' indiscriminately. While they're looking out for you I'll slip out to get my info to Regthar Deathgate.", sourceObjective = "Kill 8 Kolkar Centaur.", completion = "Oh, ho! That was beautiful. I probably shouldn't have stayed to watch. Now that they're looking for you, I'll slip quietly away in the dust of their aimless gallopin'.\n\nBe sure to look for my buds at the other pools. Boss has agents at every one.", sourceObjectiveStatus = "unverified-source-field" }
quests[13995] = { id = 13995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of Centaur Mountain", description = "We were sent here to track movements of the Kolkar centaur, but after a week of watching these dirty animals scamper all around this oasis, I'm itching to give my axe a taste of their necks. What do you say, {class}? Want to cause a little havoc with me?\n\nLet's see if we can attract the attention of their strongest warrior, Kurak.", sourceObjective = "Keep Gorgal Angerscar alive as he starts some trouble with the centaur, and help him to slay Kurak.", completion = "Aw mon, why you have to go settin' Gorgal off like that? Still, I can't argue with results. We'll need to watch these animals closely to see what they do with Kurak outta the way.\n\nMore watchin' and waitin'. Gorgal won't like that.", sourceObjectiveStatus = "unverified-source-field" }
quests[13997] = { id = 13997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You're Reading This While I'm In Combat...", description = "Dan is the most awesome programmer in the world... the World of Warcraft!\n\nIsn't it weird that you used to not be able to talk with me at all while I was fighting?  No longer, my friend, now that Dan has made significant improvements to one of my creature flags!\n\nCelebrate with me by snuffing out the lives of these awful creatures that perpetually have me in combat.", sourceObjective = "ELM Daze Target wants you to kill 5 ELM Attackers for Dan and Great Justice!", sourceObjectiveStatus = "unverified-source-field" }
quests[13998] = { id = 13998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Fungus We Trust", description = "I've cultured these unusual spores you dug up with a most magnificent cocktail of ... reagents ... that I'm fond of. I'm eager to see how my manipulated spores react to the waters of the Crossroads oases.\n\nThe Stagnant Oasis to the southeast should provide us an uncontaminated site for our experiment. Simply plant this culture in the moist soil anywhere near the oasis, and document the results for me.\n\nBe sure to cover your mouth, {class}.\n\n<Helbrim grins disarmingly.>", sourceObjective = "Plant a Fungal Culture near the Stagnant Oasis and observe the results.", completion = "Explosive spore clouds? You don't say ... tell me more. Choking? Stinging? Burning of the eyes? Was there itching? Nausea? Mortification? Delightful, DELIGHTFUL! You've certainly earned your commission, {name}.\n\nThat skin rash of yours should pass in a day or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[13999] = { id = 13999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who's Shroomin' Who?", description = "Think of the possibilities, {name}! Fast-growing fungal delivery agents for any manner of toxins. My companions in the Undercity will want to hear about this.\n\nHere are my notes and some additional samples. If we're fast, we can catch the next ship bound for the Eastern Kingdoms. Take the road east of here and follow it to the goblin town of Ratchet. Look for the Broken Keel tavern toward the south side of town and deliver these to my associate Sashya within.", sourceObjective = "Deliver Helbrim's Research to Sashya at Ratchet in North Barrens.", progress = "Who are you? Did Helbrim send you? Keep a low profile.", completion = "Quiet! Give me those notes. Were you followed here?", sourceObjectiveStatus = "unverified-source-field" }
quests[14001] = { id = 14001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Escape Pods", description = "{name}, I'm sorry, I thought you were dead!\n\nThis is just crazy. We sailed into a fight between the Alliance and Horde!\n\nYou know, our brothers and sisters still need to be rescued.\n\n<He points out all of the escape pods in the water around you.>\n\nI think I'm going to sit here a while longer and catch my breath. Can you swim around and let them out? Take my pair of thermohydratic flippers so you can get around faster.\n\nLet Sassy know that I'll swim in shortly.", sourceObjective = "Rescue 6 Goblin Survivors.", completion = "Oh, thank heavens that you survived, {name}! I thought for sure that you'd drowned when I saw you go over the side!\n\n\n\nLook at all of these folks you saved!", sourceObjectiveStatus = "unverified-source-field" }
quests[14003] = { id = 14003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlange Repair", description = "Well that didn't go as expected. I think I busted it.\n\nNo need to panic, though. Do me a favor and walk this across the way to Brak here in the camp. He'll bang this sucker back into shape real quick!", sourceObjective = "Walk the Broken Samophlange over to Brak Blusterpipe within the encampment.", progress = "Did you say ... samophlange!?", completion = "Sputtervalve scored us a Samophlange? Lemme see that thing!\n\nYeah, we can get this working again, no problem. Hand me that huge mallet...", sourceObjectiveStatus = "unverified-source-field" }
quests[14004] = { id = 14004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Samophlanger", description = "Well, that didn't work. The structural integrity of the samophlange is at an all-time low. I could add some more dials to try and fix it, but...that might make things even worse.\n\nLook what I discovered when I blocked the release valve and blew the cover off the differential casing, though: the personal stamp of \"Boss Copperplug.\"\n\nTake this back to Sputtervalve and tell him to find this Copperplug genius. When you're done here, just talk to me and I'll send you back using Brak's teleporter.", sourceObjective = "Take the Re-engineered Samophlange Wreckage back to Sputtervalve at Nozzlepot's Outpost. Talk to Wenikee to port directly to him.", progress = "Is that my samophlange? I don't even recognize it.", completion = "Wenikee said what? Copperplug? BOSS Copperplug? Oh no, this might be tricky.", sourceObjectiveStatus = "unverified-source-field" }
quests[14005] = { id = 14005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vengeance of Elune", description = "As Teldrassil purges itself of the corruption that has perverted it's growth for all of these years, a malevolent growth has formed near the tree's edge, south of here. We have an opportunity to strike out and purge the source of the fel moss that has tainted the gnarlpine, the timberlings, and everything else.\n\nWith the water that you've collected from the moonwells and the renewed strength of Teldrassil herself, I can grant you great power for a short while. Put an end to this corruption, {name}.", sourceObjective = "Use the powers granted to you by Tarindrella to fight your way to the Heart of Corruption and destroy it.", completion = "Elune be praised!\n\nEverything I had encountered suggested this corruption to be buried deep within Teldrassil itself... I had worried we might never be able to strike at the source without killing the world tree. I am thankful I was wrong!\n\nMalfurion was the start to this great turn of fortune. Perhaps I will seek him out before I depart to the wilds again.\n\nThank you, {name}. Thank you for everything you have done. You are sure to be a great hero someday!", sourceObjectiveStatus = "unverified-source-field" }
quests[14006] = { id = 14006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Read the Manual", description = "Back when I was in the Tinker's Union, Boss Copperplug was the best engineer we had. He defected to the Venture Company shortly before I left, and took his greatest techniques with him. He hoarded his secrets, doling out bits and pieces of knowledge to his trusted inner circle.\n\nIf he built the samophlange, then he's probably got the manual. Last I heard, he was operating right here, out of Boulder Lode mine to the northeast. Get the manual from him, and collect the pages from his followers.", sourceObjective = "Assemble the Samophlange Manual.", progress = "Did you find Copperplug?", completion = "You found it! Wow, it's over 600 pages, only 30 of which are intentionally left blank.\n\nLet's see. Chapter three: Backsplicing the Reverse Crankshaft Flywheel Pulley? Interesting. Chapter seven: Valve Timing for the High-Pressure Expansion Condenser!? This stuff is great! And I still don't even know what this thing does.\n\nHere, have some of my old tools. Let's fire this thing up one last time!", sourceObjectiveStatus = "unverified-source-field" }
quests[14007] = { id = 14007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady Shot", description = "I'm Bamm Megabomb, your personal trainer, <sir/ma'am>.\n\nI understand that you're interested in some new insight about being a {class}? Look no further.\n\nI think you'll gain a great deal by me teaching you how to perform a Steady Shot. It just might help you climb the corporate ladder if you know what I mean.\n\nLearn the ability from me and then practice it on a training dummy here.", sourceObjective = "Speak with Bamm Megabomb and train Steady Shot, then shoot a Training Dummy with it 3 times.", progress = "Whenever you're ready, sir.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[14008] = { id = 14008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Missiles", description = "I'm Fizz Lighter, your personal trainer, <sir/ma'am>.\n\nI understand that you're interested in some new insight about being a {class}? Look no further.\n\nI think you'll gain a great deal by me teaching you how to cast Arcane Missiles. It just might help you climb the corporate ladder if you know what I mean.\n\nLearn the spell from me and then go practice casting it a few times on a training dummy across the yard to the southeast.", sourceObjective = "Speak with Fizz Lighter and train Arcane Missiles, then cast the spell 2 times at a Training Dummy.\n\nRemember, Arcane Missiles have a chance to activate through the use of other offensive spells. Use your Fireball spell first on the Training Dummy to enable the casting of your Arcane Missiles spell.", progress = "Whenever you're ready, sir.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[14009] = { id = 14009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flash Heal", description = "I'm Sister Goldskimmer, your personal trainer, <sir/ma'am>.\n\nI understand that you're interested in some new insight about being a {class}? Look no further.\n\nI think you'll gain a great deal by me teaching you how to cast Flash Heal. It just might help you climb the corporate ladder if you know what I mean.\n\nLearn it from me and then use it to heal the injured employees around the courtyard.", sourceObjective = "Speak with Sister Goldskimmer and train Flash Heal, then cast the spell 3 times on an Injured Employee.", progress = "Whenever you're ready, sir.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[14010] = { id = 14010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eviscerate", description = "I'm Slinky Sharpshiv, your personal trainer, <sir/ma'am>.\n\nI understand that you're interested in some new insight about being a {class}? Look no further.\n\nI think you'll gain a great deal by me teaching you how to perform an Eviscerate. It just might help you climb the corporate ladder if you know what I mean.\n\nLearn the ability from me and then go practice it on a training dummy in the southeast corner of the courtyard.", sourceObjective = "Speak with Slinky Sharpshiv and train Eviscerate, then use it 3 times on a Training Dummy.\n\nRemember, Eviscerate requires combo points, so first hit the dummy with Sinister Stike.", progress = "Whenever you're ready, sir.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[14011] = { id = 14011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "I'm Maxx Avalanche, your personal trainer, <sir/ma'am>.\n\nI understand that you're interested in some new insight about being a {class}? Look no further.\n\nI think you'll gain a great deal by me teaching you how to perform a Primal Strike. It just might help you climb the corporate ladder if you know what I mean.\n\nLearn it from me and then go use it on a training dummy to the southeast.", sourceObjective = "Speak with Maxx Avalanche and train Primal Strike, then use it 2 times on a Training Dummy.", progress = "Whenever you're ready, sir.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[14012] = { id = 14012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immolate", description = "I'm Evol Fingers, your personal trainer, <sir/ma'am>.\n\nI understand that you're interested in some new insight about being a {class}? Look no further.\n\nI think you'll gain a great deal by me teaching you how to cast Immolate. It just might help you climb the corporate ladder if you know what I mean.\n\nLearn the spell from me and then cast it on a training dummy to the southeast.", sourceObjective = "Speak with Evol Fingers and train Immolate, then cast it 3 times on a Training Dummy.", progress = "Whenever you're ready, sir.", completion = "There you go, boss!\n\nCome back anytime you want more training. I'll teach you what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[14013] = { id = 14013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge", description = "<The Warrior-Matic NX-01 comes online.>\n\nBoss {name} detected. I am Warrior-Matic NX-01.\n\nInsert coins to learn how to Charge your opponents. Once trained, use Charge on a Training Dummy in the immediate area.", sourceObjective = "Speak with Warrior-Matic NX-01 and train the Charge ability, then use it on a Training Dummy.", completion = "{class}-Matic NX-01 is programmed to serve.\n\nReturn anytime you seek more training. This unit will teach you what it knows.", sourceObjectiveStatus = "unverified-source-field" }
quests[14014] = { id = 14014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Our Stuff Back!", description = "Our bombs and tools! Those sneaky monkeys to the east stole them all in the dead of night!\n\nCan you go out there and get them back for us, {name}? Without those tools, we have absolutely no way to get off of this island!", sourceObjective = "Retrieve 8 Crates of Tools.", progress = "Bomb-throwing monkeys?! The nerve!!!", completion = "<Sassy breathes a sigh of relief when she sees all of the tools and bombs that you recovered.>\n\nI thought we were doomed for sure. But now we can start working on a way to get off of this island!", sourceObjectiveStatus = "unverified-source-field" }
quests[14016] = { id = 14016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight's Curse", description = "I wanted to remove the Black Knight's remains from the tournament grounds after your victory, but Confessor Paletress insisted that he receive a decent burial. Ever since, a dark presence has lingered in the cemetery and people are afraid to go there to visit the fallen.\n\nWould you visit the cemetery just past the eastern end of the tournament grounds and see if you can discover what's happening?", sourceObjective = "Crusader Rhydalla at the Argent Tournament Grounds wants you to investigate the Black Knight's Grave.", progress = "Have you investigated the Black Knight's gravesite?", completion = "<Crusader Rhydalla frowns.>\n\nDo you think they've been planning this? I suppose it doesn't matter, but I don't like the implication that we've been playing into their hands. Whatever is going on, we have to stop it.", sourceObjectiveStatus = "unverified-source-field" }
quests[14017] = { id = 14017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Knight's Fate", description = "You said the body was taken by cultists? I can only think of one place they would have gone, Deathspeaker's Watch, the encampment on the rise west of the tournament grounds.\n\nWhatever the cultists are doing must be stopped. The rumors I've heard can only be true, then. The infamous Doctor Kohler must be among the cultists, practicing his arts. Look for a rise or an altar overlooking the cultist camp, slay the doctor, and look for proof of his plans. Slow down his work in any other way you can.", sourceObjective = "Capture Doctor Kolher's Orders at Deathspeaker's Watch, then return to Crusader Rhydalla at the Argent Tournament Grounds.", progress = "Did you find out what they're doing with the Black Knight's remains?", completion = "The doctor will not have time to complete his work, but his plan is already in motion. From what you've reported, the Lich King's servants have reanimated and empowered the Black Knight and there's no telling what the knight's master has in mind. You have done well in uncovering this plot. I will tell High Crusader Adelard of your findings and together, we will alert the tournament's participants.", sourceObjectiveStatus = "unverified-source-field" }
quests[14018] = { id = 14018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Who Would Be Forgiven", description = "The voice of the goddess spoke to you at the moonwell, {name}. The cure for Relara lies to the east at Raynewood Tower. The one who has fallen into corruption.\n\nAvrus Illwhisper seeks forgiveness and redemption. It is up to you to assist him and in so doing, hopefully help my child as well.", sourceObjective = "Speak with Avrus Illwhisper at Raynewood Tower in Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[14019] = { id = 14019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monkey Business", description = "We've got major problems with the monkeys in the jungle to the east. They've stolen all of our explosives, and now they're going around throwing them.\n\nSometimes at us!\n\nI had Fizz Lighter take some of his nitro and put it in these bananas. No monkey can resist a bunch of bananas!\n\nAll you have to do is go out there and feed them.", sourceObjective = "Feed 10 Bomb-Throwing Monkeys by tossing Nitro-Potassium Bananas to them.", completion = "They launched up into the air when they ate the bananas?! That is hilarious!\n\nI think I'm going to take a bunch out there and feed them myself!", sourceObjectiveStatus = "unverified-source-field" }
quests[14021] = { id = 14021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miner Troubles", description = "Smart mining monkeys!\n\nThey're all over the inside of the cavern, mining... with picks! It's just not natural and I'm sure it's because of the kaja'mite!\n\nNone of my miners have come back out. I don't have many left! You can see my predicament, {name}.\n\n<The foreman lowers his voice.>\n\nThese guys are nowhere near as good as my old group of jungle trolls. Ah, those were the days.\n\nMaybe you can escort my last miner here through the cavern and keep those monkeys off of him? We need that kaja'mite!", sourceObjective = "Escort the Frightened Miner through the Kaja'mite Cavern.", progress = "How did it go? How much kaja'mite were you able to get?", completion = "We've hit the mother lode!!!\n\nNow, what's all this about a pygmy witchdoctor in charge of the monkeys? Is he dead? Because if he's dead, then legally I can stake my claim... not that I wasn't going to do that anyway. By {race} law, all kaja'mite belongs to us!", sourceObjectiveStatus = "unverified-source-field" }
quests[14022] = { id = 14022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilgrim's Bounty", description = "Won't you celebrate Pilgrim's Bounty with us, {name}? It's a time for reflecting on your journeys and your good fortune, sharing plentiful food and stories with friends.\n\nYou can partake of wonderful Pilgrim's Bounty feasts near major towns by sitting at a bountiful table and serving the foods you find there.\n\nIf you're interested in learning how to cook the traditional Pilgrim's Bounty foods, seek out Gregory Tabor. You will find him just outside Stormwind's gates.", sourceObjective = "Speak with Gregory Tabor just outside the city gates of Stormwind.", completion = "If you'd like to learn to cook Pilgrim's Bounty foods, I can help. If you're not already a cook, all you have to do is train and you'll be cooking in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[14023] = { id = 14023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spice Bread Stuffing", description = "Our spice bread stuffing is the cornerstone of the Pilgrim's Bounty table. The recipe has always been a favorite in Stormwind and now it has taken its place in the bountiful cookbook.\n\nIf you are already a cook, pay a visit to the Pilgrim's Bounty vendor to get your copy of the cookbook and all the local ingredients you'll need to prepare holiday fare. And if you're not yet a cook, there's no better time to start!\n\nOnce you've made the stuffing, bring it to Jasper Moore over near the tables.", sourceObjective = "Cook 5 servings of Spice Bread Stuffing and then bring them to Jasper Moore at the feasting area just outside Stormwind's gates.", progress = "We can always use more of that delicious spice bread stuffing. It's very popular.", completion = "Excellent. This is just what we needed. It's going to be a chore keeping all the tables stocked with fresh food, but it's well worth it.", sourceObjectiveStatus = "unverified-source-field" }
quests[14024] = { id = 14024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pumpkin Pie", description = "That spice bread stuffing you made smells delicious, but no Pilgrim's Bounty feast is complete without a slice of pumpkin pie. It's another one of our favorite dishes here in Stormwind, since it uses ripe Elwynn pumpkins that only grow here.\n\nIf you don't know how to make pumpkin pie already, there's a recipe in your bountiful cookbook.\n\nWould you mind cooking up a few slices and bringing them to Edward Winslow outside Ironforge? He's bound to be running low by now.", sourceObjective = "Make 5 slices of Pumpkin Pie and bring them to Edward Winslow at the feasting area right outside Ironforge.", progress = "More pumpkin pie? Just in time.", completion = "The pumpkin pie's been a big hit up here. I've never seen a dwarf get so excited about anything made from a vegetable.", sourceObjectiveStatus = "unverified-source-field" }
quests[14028] = { id = 14028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cranberry Chutney", description = "If you haven't tried the cranberry chutney yet, you're in for a treat. It's made with the freshest tangy Wetlands cranberries. Just pick some up from the Pilgrim's Bounty vendor if you want to try your hand at making chutney.\n\nThe recipe should be in your bountiful cookbook.\n\nIf you've got some extra time on your hands, would you mind making some of the chutney and bringing it down to Jasper Moore outside Stormwind? I promised him I'd trade some for the pie you brought.", sourceObjective = "Make 5 servings of Cranberry Chutney and bring them to Jasper Moore at the feasting area outside Stormwind.", progress = "Is that cranberry chutney I smell?", completion = "Finally, the cranberry chutney I was promised. You wouldn't believe how fast the celebrants go through the stuff here.", sourceObjectiveStatus = "unverified-source-field" }
quests[14030] = { id = 14030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They're Ravenous In Darnassus", description = "Thanks for bringing the cranberry chutney. There's so much cooking to do, I hardly have time to think of anything else. And on top of my responsibilities here, Isaac Allerton in Darnassus is out of almost everything. I don't suppose you'd be willing to step in and whip up some more spice bread stuffing and pumpkin pie? The vendor should have all the ingredients you need\n\nYou should be able to find him near the feasting tables near the entrance to Darnassus just beyond the Warrior's Terrace.", sourceObjective = "Bring 5 servings of Spice Bread Stuffing and 5 Pumpkin Pies to Isaac Allerton near the entrance to Darnassus.", progress = "Have you come to partake of the Pilgrim's Bounty feast?", completion = "Thanks for bringing everything. I was starting to get worried.\n\nWhile you're here, you should try your hand at making some candied sweet potatoes.", sourceObjectiveStatus = "unverified-source-field" }
quests[14031] = { id = 14031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capturing the Unknown", description = "Heya, {name}, there are strange cave paintings and other artifacts all over the cavern.\n\nDo you think you could use your belt-mounted KTC Snapflash camera to capture images at the designated spots? Also, snap a pic of the altar in the back of the cavern.\n\nI'm sure that Sassy will want the intel.", sourceObjective = "Using your KTC Snapflash, capture images at the bouncing cameras of the three cave paintings and the pygmy altar.", completion = "What are these?\n\n<Sassy examines the pictures while listening to your tale from the Kaja'mite cavern.>\n\nClearly that pygmy witchdoctor is from some new race never seen before. Maybe we should call them {name}-ians?\n\nThey must be the ones that painted all of that stuff in the cavern. I'm not sure that I like what you're describing.\n\nIt sounds to me like they're paintings of them and us on an island with an exploding volcano!", sourceObjectiveStatus = "unverified-source-field" }
quests[14032] = { id = 14032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold Camp Cleanup", description = "Your first task is one of cleansing, {name}.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.", sourceObjective = "Kill 8 Kobold Vermin, then return to Marshal McBride.", sourceObjectiveStatus = "unverified-source-field" }
quests[14033] = { id = 14033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candied Sweet Potatoes", description = "While you're here, you might want to stock up on Teldrassil sweet potatoes. They're used to make the most delicious candied sweet potatoes you've ever tasted.\n\nIf you don't believe me, look up the recipe in your bountiful cookbook and give it a try. And if there are any extras, you might want to share them with Gregory Tabor at the feasting area just outside Stormwind. They're one of his favorites, but to hear him tell it, everything's his favorite!", sourceObjective = "Make 5 servings of Candied Sweet Potatoes and bring them to Gregory Tabor just outside the gates of Stormwind.", progress = "{name}, it's good to see you again.", completion = "Ah, candied sweet potatoes! My favorite! Did Isaac tell you?", sourceObjectiveStatus = "unverified-source-field" }
quests[14034] = { id = 14034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Club Foote", description = "All this new friction between the Alliance and the Horde was leading to windfall profits, until Rear Admiral Hartley sailed into MY harbor and started poking his prow into my business. He's been searching and seizing vessels flying horde colors with the goal of depriving them use of a neutral port.\n\nI'm not about to allow some fat-fingered human to cut into my profits! Get me the schematics of his flagship. Hartley's Chief Engineer is soaking himself at the Broken Keel Tavern just up the hill...", sourceObjective = "Get the Ship Schematics from Chief Engineer Foote at the Broken Keel Tavern in Ratchet.", progress = "You got the goods?", completion = "Ah, this is it - this is it right here! So his flagship is named \"The Bellipotent\" eh?\n\nLet's see what it'll take to send this nuisance to the bottom of the sea.", sourceObjectiveStatus = "unverified-source-field" }
quests[14035] = { id = 14035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slow-roasted Turkey", description = "Every Pilgrim's Bounty feast requires a magnificent centerpiece, and I'm not talking about a decorative horn of plenty, either. No, the focus of the meal is a magnificent roast turkey.\n\nThere's a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Elwynn Forest, so you shouldn't have a problem finding one.\n\nOnce you're done roasting them, will you bring them to Isaac Allerton near the gates of Darnassus?", sourceObjective = "Make 5 Slow-Roasted Turkeys and bring them to Isaac Allerton near the gates of Darnassus.", progress = "What brings you back to Darnassus, {name}?", completion = "These are beautiful and just in time to feed hungry feasters. Thank you, {name}. You've truly mastered all the courses of a traditional Pilgrim's Bounty meal.", sourceObjectiveStatus = "unverified-source-field" }
quests[14036] = { id = 14036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilgrim's Bounty", description = "Are you here to celebrate Pilgrim's Bounty with us? It was once a time for reflecting on your journeys and your good fortune while sharing a meal with friends. Many still mark the occasion.\n\nYou can partake of Pilgrim's Bounty feasts near major towns by sitting at a bountiful table and serving the foods you find there.\n\nIf you're interested in learning how to cook the traditional Pilgrim's Bounty foods, seek out Miles Standish. You will find him in the courtyard above Undercity.", sourceObjective = "Speak with Miles Standish in the courtyard above Undercity.", completion = "If you'd like to learn to cook Pilgrim's Bounty foods, I can help. If you're not already a cook, all you have to do is train and you'll be cooking in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[14037] = { id = 14037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spice Bread Stuffing", description = "Our spice bread stuffing is the cornerstone of the Pilgrim's Bounty table. The recipe dates from better times in Lordaeron and now it has taken its place in the traditional meal.\n\nIf you are already a cook, pay a visit to the Pilgrim's Bounty vendor to get your copy of the bountiful cookbook and all the local ingredients you'll need to prepare holiday fare. And if you're not yet a cook, there's no better time to start!\n\nOnce you've made the stuffing, bring it to William Mullins over near the tables.", sourceObjective = "Cook 5 servings of Spice Bread Stuffing and then bring them to William Mullins at the feasting area in the courtyard above the Undercity.", progress = "The tables could really use more of that spice bread stuffing.", completion = "It's a chore keeping all these tables stocked. If you stop and think about it, it's strange going to so much trouble when we needn't eat anymore.\n\n<William shrugs.>\n\nTradition is tradition.", sourceObjectiveStatus = "unverified-source-field" }
quests[14038] = { id = 14038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love it or Limpet", description = "<Gazlowe spreads the plans on the table and jabs a tiny finger aft of the ship below the waterline.>\n\nThere! The hull is thinnest here, where the crankshaft meets the paddlewheel. And it's right next to the magazine!\n\n{name}, I can't be held responsible if some enterprising Horde {class} were to attach a limpet mine to that part of the hull. Not even if I supplied the mine. And paid <him/her>. Handsomely. The ship is anchored just southeast of here... go to it!\n\nThen radio me with this stolen gnomecorder.", sourceObjective = "Plant a Limpet Mine at the thinnest part of the hull of the Bellipotent.", completion = "Excellent! I wish I could've seen the look on that Rear Admiral's face when his flagship went up like a candle. Let me use my telescope here to take a look at the damage.\n\nWhat - Whhhaaatt!? That thing is still floating? Hartley must've moved the munitions ashore in case his ship was mined.\n\nI underestimated you, Hartley... but for the last time!", sourceObjectiveStatus = "unverified-source-field" }
quests[14039] = { id = 14039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home of the Kaldorei", description = "It has been an undeniable honor to have met you. You are a testament to the nobility of your race.\n\nGo now and finish this final task. Take the waters to Tyrande Whisperwind in Darnassus.", sourceObjective = "Bring the Filled Vessel to Tyrande Whisperwind in Darnassus.", progress = "How fare you, young one?", completion = "Ah, the blessed waters from our moonwells. You have borne witness to the Spirit of the Kaldorei, then?\n\nIn recent times, I've come to find that the spirit offers more questions than it does answers, but such is the continuing nature of discovery that drives us in our darkest hours.\n\nI will offer you the simplest answers that I can. Malfurion has returned to me... to us... but harsh times are yet upon us. Staghelm is gone and the world is wracked with pain - Malfurion has much to mend, and he will need help.", sourceObjectiveStatus = "unverified-source-field" }
quests[14040] = { id = 14040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pumpkin Pie", description = "That spice bread stuffing you made is a hit, but no Pilgrim's Bounty feast is complete without a slice of pumpkin pie. It's another traditional local dish, since it uses ripe Tirisfal pumpkins that only grow around here.\n\nIf you don't know how to make pumpkin pie already, there's a recipe in your bountiful cookbook.\n\nWould you mind cooking up a few slices and bringing them to Francis Eaton outside Orgrimmar? He's bound to be running low by now.", sourceObjective = "Make 5 slices of Pumpkin Pie and bring them to Francis Eaton at the feasting area right outside Orgrimmar.", progress = "We can always use more pumpkin pie.", completion = "The pie always goes first. I think people must be skipping the meal and going directly for the dessert. Have you given it a try yet?", sourceObjectiveStatus = "unverified-source-field" }
quests[14041] = { id = 14041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cranberry Chutney", description = "Have you tried the cranberry chutney yet? It's made with fresh tangy Southfury cranberries. Just pick some up from the Pilgrim's Bounty vendor if you want to try your hand at making chutney.\n\nThe recipe should be in your bountiful cookbook.\n\nIf you've got some extra time on your hands, would you mind making some of the chutney and bringing it to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff?", sourceObjective = "Make 5 servings of Cranberry Chutney and bring them to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff.", progress = "How are you enjoying Pilgrim's Bounty, {class}?", completion = "Ah, more cranberry chutney! You wouldn't believe how fast the celebrants go through it.", sourceObjectiveStatus = "unverified-source-field" }
quests[14042] = { id = 14042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ammo Kerblammo", description = "Hartley must've unloaded all of his ordnance along the beach. Let's pull his teeth out, {name}!\n\nRun along the shore and look for his munitions stockpiles. Light 'em up and he'll be land-locked and unarmed while the Bellipotent is repaired.\n\nI'll meet you back here in Ratchet.", sourceObjective = "Destroy 5 Theramore Ammunition Stockpiles along the coast.", completion = "Hah! Beautiful work, {name}. Those Alliance cretins will never trace this back to me. Meanwhile, it's back to business as usual: smuggling, double-dealing, price-gouging... I've got a lot of work to catch up on.\n\nHere, I'll let you in on a cut of my future profits. Enjoy!", sourceObjectiveStatus = "unverified-source-field" }
quests[14043] = { id = 14043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candied Sweet Potatoes", description = "While you're here, you might want to stock up on Mulgore sweet potatoes. They're used to make delicious candied sweet potatoes, my favorite part of the Pilgrim's Bounty meal.\n\nIf you don't believe me, look up the recipe in your bountiful cookbook and give it a try. If you're headed back to Orgrimmar, bring them to Francis Eaton at the feasting area just outside the city. I've been trying to keep him supplied, but everything goes so fast over there.", sourceObjective = "Make 5 servings of Candied Sweet Potatoes and bring them to Francis Eaton just outside of Orgrimmar.", progress = "Welcome back, {name}.", completion = "So Dokin drafted you to help with the candied sweet potatoes?\n\n<Francis smiles.>\n\nIt's the only way he can keep up. Thanks for bringing these.", sourceObjectiveStatus = "unverified-source-field" }
quests[14044] = { id = 14044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undersupplied in the Undercity", description = "Thanks for bringing the candied sweet potatoes. There's so much cooking to do, I can hardly keep up. And then, Miles sends me a note saying he's on the verge of running out of stuffing and cranberry chutney. I don't suppose you'd be willing to step in and whip up some more of each? The vendor should have all the ingredients you need.\n\nYou should be able to find Miles Standish near the feasting tables in the courtyard in the ruins above Undercity.", sourceObjective = "Bring 5 servings of Spice Bread Stuffing and 5 servings of Cranberry Chutney to Miles Standish near the entrance to Undercity.", progress = "It's good to see you again. {name}.", completion = "Thanks for bringing everything. Some of the tables were starting to look a little bereft of serving dishes.", sourceObjectiveStatus = "unverified-source-field" }
quests[14045] = { id = 14045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Baron Longshore", description = "That dirty pirate Baron Longshore was the terror of these waters before the Alliance demolished his fleet and rounded up the survivors. Am I happy about it? Do I look like a bundle of joy and good cheer, {name}?\n\nLongshore raided some of my most valuable cargo before his capture. Rumor has it he buried it before he was caught. I want my goods back! Find Longshore in the Alliance camp just south of here and see if you can get him to reveal where my treasure is.", sourceObjective = "Find and speak to the notorious pirate Baron Longshore.", completion = "Hah-har! So ol' Gazzy ain't given up on his goods yet, has he? Well, looks like that ol' floppy-eared goldgrubbler jes' gave me somethin' ta bargain with.", sourceObjectiveStatus = "unverified-source-field" }
quests[14046] = { id = 14046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Baron's Demands", description = "I'm bound fer that gallows fer sure, mate. That treasure's no good to me now...\n\nUnless I can use it ta buy me life. I'll make a deal with ye, {race}. Smash these manacles and I'll tell ye where me treasure's buried.\n\nOh, me word is good, friend. I used ta be a real Baron, ye know.", sourceObjective = "If you trust him, talk to Baron Longshore to free him from his manacles.", progress = "Get on with it, mate. The guards may be back any moment. Ye know what ta do.", completion = "<The Baron rubs his sore wrists, his face widening into a malevolent grin.>\n\nOh I won't be runnin' off just yet. I'll free me mates and murder my way out of here at a time of me choosin'. As fer you - a deal's a deal. Let's talk about that treasure...", sourceObjectiveStatus = "unverified-source-field" }
quests[14047] = { id = 14047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slow-roasted Turkey", description = "Every Pilgrim's Bounty feast requires a centerpiece, and for us, that's a slow-roasted wild turkey. I can't think of anything better to bring the meal together.\n\nThere's a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Tirisfal Glades, so you shouldn't have a problem finding any.\n\nOnce you're done roasting them, will you bring them to Francis Eaton outside Orgrimmar?", sourceObjective = "Make 5 Slow-Roasted Turkeys and bring them to Francis Eaton near the gates of Orgrimmar.", progress = "What brings you back to Orgrimmar, {name}?", completion = "These look perfect. Thank you, {name}. You've truly mastered all the courses of a traditional Pilgrim's Bounty meal.", sourceObjectiveStatus = "unverified-source-field" }
quests[14048] = { id = 14048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Get Enough Turkey", description = "I've been cooking nonstop since before the start of the holiday, and I still can't keep up with the demand. I don't suppose I could persuade you to help with one of the dishes, could I?\n\nTurkey is hard to come by here, so if you could supply some slow-roasted turkeys, it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in Elwynn Forest. You should be able to buy everything else you need from any of the Pilgrim's Bounty vendors.", sourceObjective = "Bring 20 Slow-Roasted Turkeys to Caitrin Ironkettle outside Ironforge.", progress = "Did you manage to find those turkeys?", completion = "These are just what I need. Thanks, {name}. You're a lifesaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[14049] = { id = 14049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Unusual Map", description = "Here's the deal, mate: to protect me treasure map, I tattooed it onto me first mate's scalp.\n\nOf course, he's dead now, along with most of me crew. The Alliance doesn't even know what they have - his severed head is hanging from a tree at the entrance to this camp.\n\nGrab that head and take it to Gazlowe back in Ratchet.", sourceObjective = "Get the Tattooed Head from the entrance to the Alliance compound.", progress = "Was Baron Longshore alive? Do you have anything for me?", completion = "What? What is this? I send you out to fetch my treasure and you bring me a big filthy head?", sourceObjectiveStatus = "unverified-source-field" }
quests[14050] = { id = 14050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazlowe's Fortune", description = "Sink me, you were right! There's a map tattooed on the skull.\n\nThat cursed Baron - he buried my treasure right under my nose. Or, above my head, anyway. The map points to a place on the bluffs over Ratchet, to the south.\n\nFollow the road west out of the city, get atop the hill, head south, then run back towards the coast and look for an enormous tree overlooking the bay. Fetch my treasure and I'll split it with you!", sourceObjective = "Gazlowe wants you to dig up his buried treasure from atop the cliffs overlooking Ratchet.", progress = "I'm going to close my eyes, {name}. And when I open them, I expect to see wall-to-wall treasure. Deal?", completion = "Nice work, {name}!\n\nOh, the Baron tried to stop you, did he? Well, I hope you gave him a pounding.\n\nNow, I promised you a cut of the goods you recovered. Let's see... what's one percent of a half percent? Ah, here you go.", sourceObjectiveStatus = "unverified-source-field" }
quests[14051] = { id = 14051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget The Stuffing!", description = "Keeping these tables stocked can be overwhelming! I've got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don't burn.\n\nI think I've got everything covered. No, wait, I'm forgetting something. The stuffing! Oh, no. There won't be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn't take long to buy or make some stuffing and you can buy the ingredients right here.", sourceObjective = "Bring 20 Spice Bread Stuffing to Caitrin Ironkettle at the feasting area outside Ironforge.", progress = "Were you able to get that stuffing?", completion = "Thank goodness! I wouldn't be able to serve the feast without spice bread stuffing.", sourceObjectiveStatus = "unverified-source-field" }
quests[14052] = { id = 14052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take it up with Tony", description = "This pirate situation is really crimping my operation. Cap'n Garvey is attacking any vessel in sight, even the ones whose owners paid me my bogus \"protection\" money. We need to get these pirates on the take, and fast!\n\nI know just the guy, one of Garvey's Lieutenants who's open to wheeling and dealing the Dizzywig way. He's offered to arrange a little 'mutiny' for me. Once we get these guys working for us, it's all gravy, see?\n\nTalk to my boy Tony Two-Tusk on Fray Island to the south.", sourceObjective = "Talk to Tony Two-Tusk on Fray Island in Northern Barrens.", completion = "Hey hey mon, did Dizzywig send you? Good, good. Did you bring the money? No? ...what about the guns?", sourceObjectiveStatus = "unverified-source-field" }
quests[14053] = { id = 14053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Out of Cranberry Chutney Again?", description = "My husband, Jasper, was going to make more cranberry chutney, but it looks like he's busy trying to make sure there's enough candied sweet potatoes for all the guests. Would you be willing to help? If you're a cook, you can get the tangy Wetlands cranberries you'll need from the Pilgrim's Bounty vendor outside Ironforge.\n\nIf you don't feel up to cooking, you could always ask someone else to make the chutney, too.", sourceObjective = "Bring 20 servings of Cranberry Chutney to Ellen Moore at the feasting area outside Stormwind.", progress = "Were you able to get your hands on any cranberry chutney?", completion = "Thanks. This looks great, and you're a fair bit faster than Jasper, but don't tell him I said so.", sourceObjectiveStatus = "unverified-source-field" }
quests[14054] = { id = 14054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy As Pie", description = "Isaac's been hard at work helping celebrants learn about the traditional Pilgrim's Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I've been trying to keep the tables stocked with as many of the dishes as I can, but we're running out of one of Isaac's favorites, pumpkin pie.\n\nWould you be able to get some for us? If you want to make the pies yourself, you'll need to buy ripe Elwynn pumpkins from the Pilgrim's Bounty vendor outside Stormwind.", sourceObjective = "Bring 20 pieces of Pumpkin Pie to Mary Allerton at the feasting area near the gates of Darnassus.", progress = "How are those pies coming along?", completion = "These are perfect. Isaac, and everyone else, will love them!", sourceObjectiveStatus = "unverified-source-field" }
quests[14055] = { id = 14055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Says Potato", description = "My wife Ellen has enlisted my help in keeping the tables stocked, but she can't make up her mind. First I was making pumpkin pie, but now she's changed her mind and she wants candied sweet potatoes.\n\nWell, I've already started on the pie, so maybe you can help me whip up those sweet potatoes. She'll be pleasantly surprised if we can get everything she's asked for.\n\nIf you're going to cook the sweet potatoes yourself, you'll have to buy them from the Pilgrim's Bounty merchant in Darnassus. Thanks, {name}.", sourceObjective = "Bring 20 Candied Sweet Potatoes to Jasper Moore at the feasting area outside of Stormwind.", progress = "Do you have those candied sweet potatoes?", completion = "These are perfect. Thanks for helping me with this, {name}. The meal will get served on time and Ellen will be happy.", sourceObjectiveStatus = "unverified-source-field" }
quests[14056] = { id = 14056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glomp is Sitting On It", description = "What? Leave it to Dizzywig to expect a mutiny on the cheap.\n\nNo matter, mon, we can make this work. First we need the money. Cap'n Garvey likes to hoard the loot we've been earnin', money I can use to pay off my handpicked mutineers.\n\nThe treasure pile is just outside the barracks here. You'll need to take care of Cap'n Garvey's \"treasurer\" first. Now, Glomp ain't no pushover. Believe me, I tried pushing him over once. He don't budge for nothin'.", sourceObjective = "Kill Glomp and grab Glomp's Booty.", progress = "You got the cash? That money will go a long way to winnin' over the hearts and minds of heartless, thoughtless cutthroats.", completion = "Look at that. We're loaded! In mutiny, you gotta make the money first. Then when you get the money, you get the power. Let's go get some power, {name}...", sourceObjectiveStatus = "unverified-source-field" }
quests[14057] = { id = 14057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guns. We Need Guns.", description = "Now, any good mutiny is going to need serious firepower. Cap'n Garvey claimed all the best firearms for himself: A whole shipment of big, heavy dwarven flintlocks. He keeps them at his side in the other building across the island. Grab me six of those rifles and I'll distribute them to me future officers...", sourceObjective = "Gather six Heavy Dwarven Rifles.", progress = "Guns, mon. You got the stuff?", completion = "<Tony unhinges one of the weapons and peers down the barrel.>\n\nOooh, very nice. Shiny. Loud. Now we're talkin'.\n\nNot much left to do but close the deal...", sourceObjectiveStatus = "unverified-source-field" }
quests[14058] = { id = 14058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Says Potato", description = "Roberta Carter has recruited me to help prepare one of the feast dishes, candied sweet potatoes.  Normally, I'd love to help, but I've promised the hostess that I'd help her watch the tables.\n\nI'd really appreciate it if you would help me come up with those candied sweet potatoes. Roberta would never forgive me if I let her down.\n\nIf you're going to cook the sweet potatoes yourself, you'll have to buy them from the Pilgrim's Bounty merchant in Thunder Bluff. Thanks, {name}.", sourceObjective = "Bring 20 Candied Sweet Potatoes to William Mullins at the feasting area above Undercity.", progress = "Do you have those candied sweet potatoes?", completion = "Thanks, {name}. Now, I can help the hostess out and still keep my word to Roberta.", sourceObjectiveStatus = "unverified-source-field" }
quests[14059] = { id = 14059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Out of Cranberry Chutney Again?", description = "I wish I knew why we're going through cranberry chutney so fast. Sometimes, I think they're feeding it to the abominations when I'm not looking. Would you be willing to help me make up a new batch? If you're a cook, you can get the tangy Southfury cranberries you'll need from the Pilgrim's Bounty vendor outside Orgrimmar.\n\nIf you don't feel up to cooking, you could always ask someone else to make the chutney, too.", sourceObjective = "Bring 20 servings of Cranberry Chutney to Roberta Carter at the feasting area in the courtyard above Undercity.", progress = "Were you able to get your hands on any cranberry chutney?", completion = "Thanks for your help, and let me know if you ever get to the bottom of the case of the disappearing chutney.", sourceObjectiveStatus = "unverified-source-field" }
quests[14060] = { id = 14060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy As Pie", description = "Dokin and Laha have been hard at work helping celebrants learn about the traditional Pilgrim's Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I've been trying to keep the tables stocked with as many of the dishes as I can, but we're running low on pumpkin pie.\n\nWould you be able to get some for us? If you want to make the pies yourself, you'll need to buy ripe Tirisfal pumpkins from the Pilgrim's Bounty vendor outside the Undercity.", sourceObjective = "Bring 20 pieces of Pumpkin Pie to Marhara Goldwheat at the feasting area outside Thunder Bluff.", progress = "How are those pies coming along?", completion = "These are great! Thank you for helping, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14061] = { id = 14061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Get Enough Turkey", description = "I've been cooking nonstop since before the start of the holiday, and I still can't keep up with the demand. I don't suppose I could persuade you to help with one of the dishes, could I?\n\nTurkey is hard to come by here, so if you could supply some slow-roasted turkeys, it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in the Tirisfal Glades. You should be able to buy everything else you need from any of the Pilgrim's Bounty vendors.", sourceObjective = "Bring 20 Slow-Roasted Turkeys to Ondani Greatmill outside Orgrimmar.", progress = "How's your turkey hunt going?", completion = "These turkeys are exactly what I needed. Thanks for helping me out of a tough situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[14062] = { id = 14062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget The Stuffing!", description = "Keeping these tables stocked can be overwhelming! I've got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don't burn.\n\nI think I've got everything covered. No, wait, I'm forgetting something. The stuffing! Oh, no. There won't be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn't take long to buy or make some stuffing and you can buy the ingredients right here.", sourceObjective = "Bring 20 Spice Bread Stuffing to Ondani Greatmill outside Orgrimmar.", progress = "Were you able to get that stuffing?", completion = "Perfect timing! I wouldn't be able to serve the feast without spice bread stuffing.", sourceObjectiveStatus = "unverified-source-field" }
quests[14063] = { id = 14063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutiny, Mon!", description = "Now for my favorite part of any mutiny: the killin'! For pirates, it doesn't matter who's supposed to be in charge, only who's in control of the ships. Anchored on the east end of this island is the Maiden's Dagger, Cap'n Garvey's old flagship. He left his most trusted officer in charge: Alicia Cuthbert. Once we take her out, the ship is ours, and so's the sea.\n\nI'll get the men onto the boats. I need you to board the Dagger and blow this horn from on deck - that'll be our signal to board. Yar!", sourceObjective = "Use the Pirate Signal to summon Tony Two-Tusk and his crew to the Maiden's Dagger. Help him to defeat Alicia Cuthbert below decks.", progress = "Is that the Maiden's Dagger I see weighing anchor in the distance? Did you have anything to do with that?", completion = "So Tony is running the show there now? Good! We need more pirates like him in these waters. He's a real businessman.\n\n<Dizzywig rubs his hands together greedily.>\n\nSpeaking of business, I suppose I owe you a cut. Would you be interested in insuring any of your new loot? You never know what can happen in a town like this...", sourceObjectiveStatus = "unverified-source-field" }
quests[14064] = { id = 14064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing a Bountiful Feast", description = "You've not celebrated Pilgrim's Bounty properly until you've eaten your fill at a Bountiful Table.\n\nPlease, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food.\n\nOnce you eat enough of every dish, you'll be infused with the Spirit of Sharing.", sourceObjective = "Eat five helpings of every food at a Bountiful Table until you gain the Spirit of Sharing.", progress = "Did you eat enough at a Bountiful Table?", completion = "What a feast, hmmm?\n\nI'm so glad you could celebrate the spirit of Pilgrim's Bounty with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[14065] = { id = 14065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing a Bountiful Feast", description = "You've not celebrated Pilgrim's Bounty properly until you've eaten your fill at a Bountiful Table.\n\nPlease, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food.\n\nOnce you eat enough of every dish, you'll be infused with the Spirit of Sharing.", sourceObjective = "Eat five helpings of every food at a Bountiful Table until you gain the Spirit of Sharing.", progress = "Did you eat enough at a Bountiful Table?", completion = "What a feast, hmmm?\n\nI'm so glad you could celebrate the spirit of Pilgrim's Bounty with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[14066] = { id = 14066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Wreckage", description = "Not long ago, a shipment of silver was stolen en route from here to Crossroads. It was meant as payroll to the guards, and we want that silver back.\n\nI'll ask around here for clues, but I want you to investigate the scene of the crime. Head west and look for a crashed caravan wagon just north of the road between here and Crossroads. Find out who took our silver and get it back!", sourceObjective = "Find the wrecked caravan near the road between Ratchet and Crossroads and search the area for clues.", completion = "This Horde caravan was not merely robbed. It was savagely brutalized. Crates of supplies have been ripped apart by sharp claws. The wagon has been demolished. The food has been eaten and the silver is gone, and yet useful supplies have been left behind...", sourceObjectiveStatus = "unverified-source-field" }
quests[14067] = { id = 14067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stolen Silver", description = "It's clear that these raptors acted alone to steal the Horde's silver.\n\nIt's time to teach these beasts a lesson.", sourceObjective = "Kill 8 Sunscale Ravagers, 4 Sunscale Scytheclaws, and locate the Stolen Silver.", progress = "You look roughed up, {class}. Did you tussle with the thieves?", completion = "<Gazrog opens the lockbox and begins counting up the silver while you relate your story.>\n\nWhat!? Raptors? Just the raptors? Assaulting our caravans and looting them? Perhaps they are as intelligent as the rumors say. As if we didn't have enough problems, now we've got to deal with brainy lizards with a lust for coin.\n\nHere, {name} - you've earned a share of the rescued silver. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[14068] = { id = 14068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waptor Twapping", description = "Waptor twapping can be wough, but I've designed new waptor twaps that ewiminate much of the wisk.\n\nSet the twap on the gwound and it will scweech wike a waptor, luwing one into the twap.\n\nWhen a waptor steps on my waptor twap, it'll shwink down so that it's wess dangewous. It's wewwy easy! I would do it myself but wecentwy I wan acwoss King Weapercwaw.", sourceObjective = "Use Kala'ma's \"Waptor Twap\" to capture 5 Wittle Waptors.", progress = "Where's the wittle waptors?", completion = "Hooway! You twapped the waptors I was wooking for! Now we will twain them for twolls to wide to swaughter the Awwiance!", sourceObjectiveStatus = "unverified-source-field" }
quests[14069] = { id = 14069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Help is Hard to Find", description = "I've failed! I tried to meet our Kaja'Cola quotas, but you know troll slaves these days. Good help is hard to find!\n\nI think your personal touch is called for. A shock from the battery on your Goblin All-In-1-Der Belt should do the trick. Adjust their attitudes and the rest will fall in line.\n\nKaja'Cola production must continue or the Trade Prince will have all of our heads!", sourceObjective = "Adjust the attitudes of 8 Defiant Trolls.", progress = "A good start, sir, but might I suggest that you may want to make an example of a few more?", completion = "I couldn't have done better myself. In fact, I didn't.\n\nI'm sure that in no time at all we'll all be talking about the great and powerful, and may I add extremely wealthy, Trade Prince {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14070] = { id = 14070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do it Yourself", description = "We need to send a message to several deadbeats. Of course, they're hiding out in Drudgetown, the scum. I know how you hate going into the slums, boss-<man/lady>, but what can we do?\n\n<Sassy rifles through some paperwork.>\n\nI have all of the names right here.\n\nMight I suggest a little 'personal visit'? A couple of strategic beatdowns will send a message to the other debtors AND your competition.\n\n{name} is not a goblin to be trifled with!", sourceObjective = "Beat down Bruno Flameretardant, Frankie Gearslipper, Jack the Hammer, and Sudsy Magee.", completion = "A complete success if I do say so myself, sir! Your debtors will think twice now about not paying up!\n\n<Sassy taps her pencil against her lower lip for a moment, deep in thought.>\n\nPerhaps we should increase interest rates on loans across the board?", sourceObjectiveStatus = "unverified-source-field" }
quests[14071] = { id = 14071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolling with my Homies", description = "{name}, you're about to host the corporate party to end all corporate parties. My research says that if you're seen having a good time at the party, your promotion quotient will skyrocket and explode!\n\nSo, with that in mind, might I suggest that you take your new company hot rod out for a spin?\n\nGo pick up your friends. Just remember me on the way up when it all comes together and you're the new Trade <Prince/Princess>, okay?", sourceObjective = "Drive the Hot Rod around and pick up your friends: Ace, Gobber, and Izzy.", progress = "The party's almost ready. How was your trip to town?", completion = "Well done, sir. You all look very good riding around in the hot rod. I'm sure you made quite an impression on the citizenry.", sourceObjectiveStatus = "unverified-source-field" }
quests[14072] = { id = 14072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flushing Out Verog", description = "Regthar Deathgate sent me here to observe the centaur activity, but the leader of this group is hard to pin down. I've discovered that his name is \"Verog the Dervish,\" but his whereabouts are a mystery.\n\nCan you help me do some digging? I know that \"Centaur Intelligence\" sounds like an oxymoron, but their camps are often littered with important communications. Search the centaur tents all around the Stagnant Oasis here and bring me back some info.", sourceObjective = "Gather 4 pieces of Centaur Intelligence from around the Stagnant Oasis.", progress = "Search those tents, {name}. Try to ignore the stench.", completion = "Good work, {name}. Did you look through these? They're barely legible - more like angry graffiti than war plans. Hatred, jealousy, rage, personal conflicts - it's a wonder Verog can keep these centaur from killing each other, much less form them into an army.\n\nWe can use this to our advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[14073] = { id = 14073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathgate's Reinforcements", description = "{name}! Your reputation among the Horde grows. I've been hearing reports from both the Forgotten Pools and the Stagnant Oasis that you've been a real bane to our centaur foes. Well done, indeed.\n\nRegthar Deathgate is in charge of our operations against the centaur all over the Northern Barrens. He could use a bold {class} like yourself to bolster his forces. Report to him at his outpost along the road west of here and aid him in any way he requires.", sourceObjective = "Report to Regthar Deathgate at his outpost west of the Crossroads in Northern Barrens.", completion = "Ah, I've heard about your work, {class}. Your timing is fortunate - I've got a major offensive in the works.", sourceObjectiveStatus = "unverified-source-field" }
quests[14074] = { id = 14074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Leg Up", description = "The Argent Crusade dispatched a fast ship carrying tallstrider meat and other supplies for us here at the tournament grounds, but it never arrived. Scouts reported seeing it attacked by the Kvaldir, fearsome vrykul raiders who roam the seas.\n\nThey've slain the crew and taken the cargo to an island called Hrothgar's Landing. If you look to the north, you can see it shrouded in the mist. Would you help us in recovering the stolen supplies? Without those tallstrider legs, we'll soon be out of food.", sourceObjective = "Recover 10 Stolen Tallstrider Legs for Narasi Snowdawn at the Argent Tournament Grounds.", progress = "Were you able to recover any of the missing supplies?", completion = "These look a little worse for wear, but they're still edible. The crusaders will be glad to hear that we've managed to recover some of the ship's cargo.", sourceObjectiveStatus = "unverified-source-field" }
quests[14075] = { id = 14075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in the Mines", description = "We've got trouble down in the Kaja'mine again, boss. The tunneling worms have returned and they're literally eating away at the Kajaro Trading Company's profits!\n\nKaja'mite mining is down, which is negatively impacting our production of Kaja'Cola!\n\nI tried calling the exterminator, but he's fled with the last payment we made to him.\n\nDo you think you could head into the three mines and take care of it? I'd help but I still haven't attended the cartel-mandated fighter training seminar.", sourceObjective = "Slay 6 Tunneling Worms.", completion = "I say good riddance to those pests!", sourceObjectiveStatus = "unverified-source-field" }
quests[14076] = { id = 14076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breakfast Of Champions", description = "Now that the coliseum is complete, the Argent Crusade has asked us to help look after the creatures that champions will be fighting.\n\nThe giant jormungar have perhaps the strangest diet; they grow strong by eating the eggs of their own kind and the best eggs come from deep jormungar.\n\nTake this drum to the Foot Steppes in central Storm Peaks and play them near the snow mounds you see there.  Rouse the deep jormungar, kill them, and gather their egg sacs.", sourceObjective = "Acquire 4 Jormungar Egg Sacs and bring them to Savinia Loresong at the Argent Tournament Grounds.", progress = "Were you able to get those eggs? Those worms will start eating their handlers if they're not fed soon.", completion = "Well done, {name}. I'll take these to the Argent Crusade's keepers right away. They'll have no choice but to acknowledge that we're doing far more than the Sunreavers to keep the coliseum running smoothly.", sourceObjectiveStatus = "unverified-source-field" }
quests[14077] = { id = 14077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light's Mercy", description = "I've been listening to Confessor Paletress speak, and I must tell you, her words have given me much to consider. It is not enough to fight beside the crusaders; we must take up their mission.\n\nOff the north coast is Hrothgar's Landing, where the seagoing Kvaldir have overrun an old tuskarr settlement and slain the villagers. Take this book and read the rites for the dead near the corpses of the villagers. It will allow their spirits to escape the mists engulfing the island and find peace.", sourceObjective = "Use the Confessor's Prayer Book to perform last rites for 8 Slain Tualiq Villagers and then return to Narasi Snowdawn at the Argent Tournament Grounds.", progress = "Have you seen to the spirits of the slain Tualiq villagers?", completion = "<Narasi accepts the prayer book from you.>\n\nThank you. The book was a gift from Confessor Paletress herself. She would  be honored to know that you have used it to bring tranquility to the slain.", sourceObjectiveStatus = "unverified-source-field" }
quests[14078] = { id = 14078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lockdown!", description = "What are you still doing here, citizen?  Haven't you heard?  The city's under complete lockdown.\n\nGo see Lieutenant Walden -- he'll give you further directions for evacuation.", sourceObjective = "Find Lieutenant Walden in the northwestern end of the Merchant Square.", completion = "Deep claw marks run through the man's corpse.", sourceObjectiveStatus = "unverified-source-field" }
quests[14079] = { id = 14079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Elwynn Forest", description = "This pamphlet advertising riding training and mount purchases was sent from Randal Hunter.\n\nRandal can be found at Elwynn Forest's Eastvale Logging Camp, along the road east out of Stormwind.", sourceObjective = "Return the pamphlet to Randal Hunter at Eastvale Logging Camp in Elwynn Forest.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", sourceObjectiveStatus = "unverified-source-field" }
quests[14080] = { id = 14080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop The Aggressors", description = "The Kvaldir, fearsome vrykul raiders, have disrupted our shipments and murdered the tuskarr inhabitants of an island to the north, renaming it Hrothgar's Landing. If they are allowed to get a foothold there, there is no doubt that we will be their next target.\n\nThe crusade's forces have their hands full dealing with the Scourge, and we must defend the tournament grounds. Fly north from the grounds until you reach the island and take on the Kvaldir before they can destroy anything else.", sourceObjective = "Narasi Snowdawn at the Argent Tournament Grounds wants you to kill 10 Kvaldir.", completion = "Your actions have shown that we stand as one with the Argent Crusade, while the Sunreavers are too busy preening to take up their blades.", sourceObjectiveStatus = "unverified-source-field" }
quests[14081] = { id = 14081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in the Eversong Woods", description = "This pamphlet advertising riding training and mount purchases was sent from Perascamin.\n\nPerascamin can be found at Thuron's Livery, southeast of the Shepherd's Gate leaving Silvermoon City.", sourceObjective = "Return the pamphlet to Perascamin at Thuron's Livery in Silvermoon City.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", sourceObjectiveStatus = "unverified-source-field" }
quests[14082] = { id = 14082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride at the Exodar", description = "This pamphlet advertising riding training and mount purchases was sent from Aalun.\n\nAalun can be found at the entrance to the Exodar on Azuremyst Isle.", sourceObjective = "Return this pamphlet to Aalun outside the Exodar on Azuremyst Isle.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", sourceObjectiveStatus = "unverified-source-field" }
quests[14083] = { id = 14083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Dun Morogh", description = "This pamphlet advertising riding training and mount purchases was sent from Ultham Ironhorn.\n\nUltham can be found at the Amberstill Ranch in Dun Morogh, found along the road east out of Ironforge.", sourceObjective = "Return the pamphlet to Ultham Ironhorn at Amberstill Ranch in Dun Morogh.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", sourceObjectiveStatus = "unverified-source-field" }
quests[14084] = { id = 14084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Dun Morogh", description = "This pamphlet advertising riding training and mount purchases was sent from Binjy Featherwhistle.\n\nBinjy can be found at Steelgrill's Depot, just northeast of Kharanos in Dun Morogh.", sourceObjective = "Return the pamphlet to Binjy Featherwhistle at Steelgrill's Depot in Dun Morogh.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", sourceObjectiveStatus = "unverified-source-field" }
quests[14085] = { id = 14085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Darnassus", description = "This pamphlet advertising riding training and mount purchases was sent from Jartsam.\n\nJartsam can be found at the Cenarion Enclave in Darnassus.", sourceObjective = "Return the pamphlet to Jartsam at the Cenarion Enclave in Darnassus.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", sourceObjectiveStatus = "unverified-source-field" }
quests[14086] = { id = 14086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Orgrimmar", description = "This pamphlet advertising riding training and mount purchases was sent from Kildar.\n\nKildar can be found in Orgrimmar's Valley of Honor.", sourceObjective = "Return the pamphlet to Kildar in Orgrimmar's Valley of Honor.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", sourceObjectiveStatus = "unverified-source-field" }
quests[14087] = { id = 14087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Mulgore", description = "This pamphlet advertising riding training and mount purchases was sent from Kar Stormsinger.\n\nKar can be found in Mulgore's Bloodhoof Village.", sourceObjective = "Return the pamphlet to Kar Stormsinger at Bloodhoof Village in Mulgore.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", sourceObjectiveStatus = "unverified-source-field" }
quests[14088] = { id = 14088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Durotar", description = "This pamphlet advertising riding training and mount purchases was sent from Xar'Ti.\n\nXar'Ti can be found at Sen'jin Village in southern Durotar.", sourceObjective = "Return the pamphlet to Xar'Ti at Sen'jin Village in southern Durotar.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", sourceObjectiveStatus = "unverified-source-field" }
quests[14089] = { id = 14089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn to Ride in Tirisfal Glades", description = "This pamphlet advertising riding training and mount purchases was sent from Velma Warnam.\n\nVelma can be found at Brill in Tirisfal Glades.", sourceObjective = "Return the pamphlet to Velma Warnam at Brill in Tirisfal Glades.", progress = "Ah, you received my letter? Good.", completion = "So, shall we begin your Apprentice Riding training?", sourceObjectiveStatus = "unverified-source-field" }
quests[14090] = { id = 14090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok Wants His Snobolds", description = "Two of my men have already been killed trying to confine the magnataur called Gormok the Impaler, yet the creature still rages. It howls for hours about being without its favorite snobold.\n\nIf the Argent Crusade didn't wish to use this monster in the coliseum, I'd slay it myself. Perhaps it's time to bring the beast its playthings. Take this net and travel to Garm's Bane in southeast Storm Peaks. It's just northeast of K3. Capture some of those snobolds and pray to the Light you've found the right one.", sourceObjective = "Use the Weighted Net to capture 8 Snowblind Followers and bring them to Savinia Loresong at the Argent Tournament Grounds.", progress = "Have you managed to round up those snobolds yet? Gormok's anger shows no signs of lessening.", completion = "The sooner we get these stinking things out of my sight and into their cage, the faster my mood will improve. I wish the Argent Crusade had given the Sunreavers the care of this creature. They're enough alike that they ought to be able to understand each other.", sourceObjectiveStatus = "unverified-source-field" }
quests[14091] = { id = 14091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something's Amiss", description = "The lieutenant appears to have died from severe wounds.  The prince might want to hear this news.\n\nYou hear the sound of fighting coming from the market.", sourceObjective = "Return to Prince Liam Greymane in the Merchant Square.", completion = "It's you again.  Looks like you're not one to hide in the face of danger.  Very well, then.", sourceObjectiveStatus = "unverified-source-field" }
quests[14092] = { id = 14092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breakfast Of Champions", description = "Now that the coliseum is complete, the Argent Crusade has asked us to help look after the creatures that champions will be fighting.\n\nThe giant jormungar have perhaps the strangest diet; they grow strong by eating the eggs of their own kind and the best eggs come from deep jormungar.\n\nTake this drum to the Foot Steppes in central Storm Peaks and play them near the snow mounds you see there. The sound will rouse the deep jormungar. Kill them, collect their egg sacs, and return to the tournament grounds.", sourceObjective = "Acquire 4 Jormungar Egg Sacs and bring them to Tylos Dawnrunner at the Argent Tournament Grounds.", progress = "Were you able to get those eggs? The jormungar are going to get nasty if they don't get fed.", completion = "I'll let the crusaders know that you've just returned with a fresh load of food while the Silver Covenant was sitting on its heels.", sourceObjectiveStatus = "unverified-source-field" }
quests[14093] = { id = 14093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Hell Breaks Loose", description = "Worgen!  My father had warned me that Archmage Arugal's creations had run amok.\n\nBut where are they coming from?\n\nI suppose it doesn't matter.  Help us make quick work of them.  We'll show them what we Gilneans are made of!", sourceObjective = "Prince Liam Greymane wants you to slay 6 Rampaging Worgen.", progress = "Have the {race} been dealt with?", completion = "It's no use, {name}!  They're not letting up.", sourceObjectiveStatus = "unverified-source-field" }
quests[14094] = { id = 14094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvage the Supplies", description = "Listen, {name}.  We can't let our supplies get destroyed.\n\nWith Gilneas walled off from the outside world, we won't last through winter if we lose much more of our stock.\n\nPlease help me salvage what you can.", sourceObjective = "Salvage 4 Supply Crates.", progress = "Have you salvaged the supplies, {name}?", completion = "Excellent!  I'll make sure these get taken to a safe place.", sourceObjectiveStatus = "unverified-source-field" }
quests[14095] = { id = 14095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Identifying the Remains", description = "A whole tooth from a dead Kraken is a rare find indeed.  Crusader Silverdawn will want to see this.", sourceObjective = "Take the Kraken Tooth to Crusader Silverdawn as proof of your victory.", progress = "What have you found, Champion?", completion = "I knew that Kraken was not a match for the likes of you.  Without that Kraken disrupting those boats, those Kvaldir will have no choice but to retreat.  Great job, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[14096] = { id = 14096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You've Really Done It This Time, Kul", description = "Crusader Kul has gone and gotten himself into trouble again, only this time he's not alone. When he saw the cultists making camp at Deathspeaker's Watch, west of the tournament grounds, Kul gathered the aspirants for an assault.\n\nWithout reinforcements, Kul and his followers were easily captured. I have no doubt that the cult will sacrifice the prisoners unless we can mount a rescue. Any of those cultists could carry keys to the black cages. Find the keys and free Kul and the captive aspirants.", sourceObjective = "Rescue Kul the Reckless and 4 Captive Aspirants from Deathspeaker's Watch and return to Narasi Snowdawn at the Argent Tournament Grounds.", completion = "Thanks to you, Kul and the aspirants will live fight the Scourge again. That's far from the first time someone's had to save Kul from himself. My only hope is that the crusaders can find a better outlet for his enthusiasm than allowing him to impart all of his bad habits to impressionable young aspirants.", sourceObjectiveStatus = "unverified-source-field" }
quests[14098] = { id = 14098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evacuate the Merchant Square", description = "The civilians aren't safe here anymore.  Not even inside their homes.\n\nWe're doing our best to stop the worgen from getting indoors, but their numbers are too great.\n\nHelp us by evacuating the civilian homes.  My father's army in the prison district will be able to better protect them.", sourceObjective = "Evacuate 3 Civilian Homes.", completion = "Good job, {name}.  Thanks to you, many Gilneans will live to see another day.", sourceObjectiveStatus = "unverified-source-field" }
quests[14099] = { id = 14099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Royal Orders", description = "It's time for you to leave, {name}.  Go to the Military District with the other civilians.\n\nCheck in with Gwen Armstead when you cross the bridge to the southeast... see if everyone's okay.\n\nI will stay here with the guards and cover the civilians' retreat.\n\nGo now.  That is an order!", sourceObjective = "Speak to Gwen Armstead in the Military District to the southeast.", completion = "We're all fine here.  A little shaken... but alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[14100] = { id = 14100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic of the Earthen Ring", description = "You have progressed far in your training, {name}. Now that you have mastered the four basic elements, you must strive to keep all four in balance. There is a practical benefit to this discipline - with practice, you may carry only a single relic instead of all four totems.\n\nSpeak to Gotura Fourwinds at the Valley of Wisdom in Orgrimmar, and hone your mastery of the elements.", sourceObjective = "Bring your four totems to Gotura Fourwinds in Orgrimmar.", progress = "Hmmm, what brings you to seek the aid of the Earthen Ring?", completion = "Ah, you've mastered the four totems. You should be proud of your accomplishments so far, young {race}, but this is only the beginning of your journey.\n\nHere, accept this gift from the Earthen Ring. Carry this relic with you and you will have the power of all four elements at your command.\n\nContinue your training, friend. Grave challenges are ahead for this world - I can hear it in the wind and feel it in the rumblings of the earth. We must be prepared for the worst.", sourceObjectiveStatus = "unverified-source-field" }
quests[14101] = { id = 14101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drottinn Hrothgar", description = "The Kvaldir, seafaring vrykul who raid ships and coastal settlements, have overrun a tuskarr  island across the strait to the north. Their leader is a veteran raider, Drottinn Hrothgar, who seeks to control these seas.\n\nWith him in power, our shipments and troop transports will never be safe. We will be stranded here at the Lich King's mercy.\n\nTake this captured Kvaldir war horn to the circle of tuskarr statues on the northeastern part of Hrothgar's Landing and use it to challenge the Kvaldir leader.", sourceObjective = "High Crusader Adelard at the Argent Tournament Grounds wants you to defeat Drottinn Hrothgar.", completion = "The defeat of the drottinn will set the kvaldir to fighting amongst themselves, buying us time to use our advantage. The crusade and the tournament are in your debt, champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[14102] = { id = 14102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistcaller Yngvar", description = "The Kvaldir have returned to the coasts of Northrend and if left unchecked, they will prevent our supplies and reinforcements from arriving. One of them, known as Mistcaller Yngvar, has taken up residence in a cave on the western side of Hrothgar's Landing. There, he manipulates the mists to conceal the Kvaldir and  the sea beasts they command.\n\nTake this charm and travel across the strait north of the tournament grounds, to Hrothgar's Landing. Find the mistcaller's cave and use the charm to reveal him.", sourceObjective = "High Crusader Adelard at the Argent Tournament Grounds wants you to kill Mistcaller Yngvar.", completion = "You have bought us valuable time to move against the Kvaldir and free the seas of these pests. Once again, the Argent Crusade is in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14103] = { id = 14103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanium Powder", progress = "Hello {name}!  Do you have anything to trade?", completion = "Wonderful!  Another batch of powder!\n\nJust between us jewelcrafters, I've been making hand over fist selling \"pure titanium\" jewelry to the local Dalaran mages.  Even with their superior intellect, they aren't particularly savvy with their gold.  If you get more, I'll be here." }
quests[14104] = { id = 14104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ornolf The Scarred", description = "Ornolf the Scarred is a fearsome raider renowned among his Kvaldir brethren for raiding and capturing ships. From aboard Bor's Fury, he and his crew attack our ships and steal our goods.\n\nOrnolf and his men are among those who slaughtered the inhabitants of a tuskarr island to the north and renamed it Hrothgar's Landing. His ship sits at anchor at the eastern end of the island's harbor. Take this captured banner and display it on his ship to provoke him into facing you in battle.", sourceObjective = "High Crusader Adelard at the Argent Tournament Grounds wants you to kill Ornolf the Scarred.", completion = "Ornolf's crew will want to avenge their leader, but without him, they will be easier to defeat. We must live to carry out our mission, to see Icecrown rid of the Scourge and other evils.", sourceObjectiveStatus = "unverified-source-field" }
quests[14105] = { id = 14105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathspeaker Kharos", description = "The Cult of the Damned has redoubled its efforts to see us destroyed. They have grown bold and are massing their strength at Deathspeaker's Watch on the ridge west of the tournament grounds.\n\nThe ruthless Deathspeaker Kharos has his men fortifying their positions, preparing to unleash all of the cult's weapons.\n\nMy men are preparing themselves and the valiants to defend the grounds, but I want champions like you, {name}, to lead our efforts to blunt the attack. Find Deathspeaker Kharos and slay him.", sourceObjective = "High Crusader Adelard at the Argent Tournament Grounds wants to you kill Deathspeaker Kharos.", completion = "You are truly an example to all who have gathered beneath our banner, {name}. Together, we will show the Scourge that we will not be defeated.", sourceObjectiveStatus = "unverified-source-field" }
quests[14106] = { id = 14106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Na Kada's Quest Test" }
quests[14107] = { id = 14107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate Of The Fallen", description = "The Argent Crusade is hardly the first force to challenge the Lich King. Our enemy turns spirits of the fallen against us.\n\nTheir spirits wander the Valley of Fallen Heroes, southwest of the grounds and between Aldur'thar and the Ironwall Rampart. The area is littered with discarded soul crystals, used by the Scourge to control the spirits. Gather those soul crystals and use them with this Light-blessed relic to bestow the blessing of peace upon the spirits. They have more than earned their rest.", sourceObjective = "Crusader Silverdawn wants you to bring peace to 6 Fallen Hero's Spirits.", progress = "Have you brought peace to the spirits of the fallen heroes?", completion = "You have done our fallen brethren a great service and spared us the need to face them again on the field of battle. As our campaign against the Scourge progresses, I find myself thinking about my own fate.\n\nShould I fall, {name}, I would want someone like you to do for me what you have done for the spirits of the fallen this day. I could not bear the thought of forcing my own brothers to slay me again and again.", sourceObjectiveStatus = "unverified-source-field" }
quests[14108] = { id = 14108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Kraken!", description = "The Sunreavers and Silver Covenant sent ships north to engage the Kvaldir at Hrothgar's Landing, but were intercepted and detained by a Kvaldir Raiding vessel.  To make matters worse, the Kvaldir have found a way to call forth the dreaded Kraken that lives beneath the North Sea.  If anyone on board is to get out alive, that Kraken must be driven away and the Kvaldir's summoning ritual ... disrupted.\n\nCrusader, take these spears and an Argent Hippogryph will take you to the battle.", sourceObjective = "Crusader Silverdawn wants you to mount an Argent Hippogryph, throw 8 Flaming Spears at the North Sea Kraken and take out 6 Vrykul Deepcallers.\n\nYou can find the Argent Hippogryphs right outside the Argent Crusade tent at the Tournament Grounds.", progress = "Have you driven away the Kraken yet?  Hurry, Crusader! There isn't much time.", completion = "Crusader, you may have bought those sailors just enough time to escape,  Maybe next time, those Silver Covenant and Sunreavers will listen before running head first at the enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[14109] = { id = 14109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New You", description = "A new outfit? You don't say! There's quite a buzz surrounding your party. Everyone who's anyone on the island is going to be there.\n\nWell, happy shopping. Swindle Street has some of the best bargains anywhere!", sourceObjective = "Buy some Shiny Bling from Gappy Silvertooth, a Hip New Outfit from Szabo, and some Cool Shades from Missa Spekkies on Swindle Street.", progress = "Do you have it all, {name}? I can't wait to see it on you!\n\nYou bought the good stuff, right?", completion = "Oh, you are going to look so fine, but not as gorgeous as me! You're going to replace the Trade Prince any day now at the rate you're going!\n\nI can't wait to not have to work anymore! You're going to buy me everything that I want, right babe?\n\nLet me have all that stuff and I'll help you get into it right before the party.", sourceObjectiveStatus = "unverified-source-field" }
quests[14110] = { id = 14110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New You", description = "A new outfit? You don't say! There's quite a buzz surrounding your party. Everyone who's anyone on the island is going to be there.\n\nWell, happy shopping. Swindle Street has some of the best bargains anywhere!", sourceObjective = "Buy some Shiny Bling from Gappy Silvertooth, a Hip New Outfit from Szabo, and some Cool Shades from Missa Spekkies on Swindle Street.", progress = "Do you have it all? I can't wait to see it on you!\n\nMmm hmm!", completion = "Oh yeah, you're going to look hot! You're going to replace the Trade Prince any day now at the rate you're going!\n\nI can't wait to be a kept man!\n\nLet me have all that stuff and I'll help you get into it right before the party.", sourceObjectiveStatus = "unverified-source-field" }
quests[14111] = { id = 14111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic of the Earthen Ring", description = "You have progressed far in your training, {name}. Now that you have mastered the four basic elements, you must strive to keep all four in balance. There is a practical benefit to this discipline - with practice, you may carry only a single relic instead of all four totems.\n\nSpeak to Farseer Eannu near the Great Forge in Ironforge. He will help you hone your mastery of the elements.", sourceObjective = "Bring your four totems to Farseer Eannu in Ironforge.", progress = "The spirits stir within you. What brings you to seek the aid of the Earthen Ring?", completion = "I see you've mastered use of the four totems. You are on your way to becoming one with the elemental spirits, but this is only the beginning of your journey.\n\nHere, accept this gift from the Earthen Ring. Carry this relic with you and you will have the power of all four elements at your command.\n\nYour training must continue! I sense a great many trials lie ahead for this world, and we will need the power of the elements behind us if we are to prevail.", sourceObjectiveStatus = "unverified-source-field" }
quests[14112] = { id = 14112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Do You Feed a Yeti, Anyway?", description = "The crusaders have captured a yeti that they're calling Icehowl. He's to be a participant in the coliseum battles and we've been asked to help with his training and upkeep.\n\nThe crusaders weren't fond of my suggestion that we feed the beast surplus Sunreavers. The creature has a predilection for shark meat, so I want you to fly down to the Silver Blade, floating in the strait to the north. Get some fresh chum from one of the buckets on the boat, then spread it in the water to attract sharks.", sourceObjective = "Savinia Loresong at the Argent Tournament Grounds wants you to bring her 3 pieces of North Sea Shark Meat.", progress = "I hope you have something to feed Icehowl, otherwise I really will start bringing Sunreavers down to his cage.", completion = "I'm glad we've gotten that done. It's not the most glorious task in the world, but when we partnered with the Argent Crusade, we promised to do all they asked of us without complaint. Of course, the same cannot be said of the Sunreavers.", sourceObjectiveStatus = "unverified-source-field" }
quests[14113] = { id = 14113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life of the Party", description = "Oh my gosh, babe! Everyone is here! Who cares about some stupid dragon?\n\nWe setup the party around the pool. Sounds like they're having a great time. You are going to look so good!\n\nWhy don't you head over to the pool and keep everyone entertained? I'll join you in a moment... I just have to slip into something even more amazing!", sourceObjective = "Put on your Awesome Party Ensemble (Cool Shades, Hip New Outfit, and Shiny Bling) and then head over to the party at the KTC Headquarters pool to entertain 10 Kezan Partygoers.", progress = "How's the party going?\n\nYou look amazing! So dashing and handsome, sir!", completion = "Very nicely done, sir. The party appears to have been a smashing success!\n\nEr... what's that?", sourceObjectiveStatus = "unverified-source-field" }
quests[14115] = { id = 14115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirate Party Crashers", description = "Oh my gosh! Pirates!\n\n{name}, there are Southsea pirates crashing your party!\n\nYou have to get in there and do something about this or your career, and any chance of you being the next Trade <Prince/Princess>, is going to be ruined!", sourceObjective = "Kill 12 Pirate Party Crashers in order to save your career.", progress = "Was that all of them? I know that I saw a lot rushing in!", completion = "Phew, that was close, boss. Unfortunately, I'm the bearer of more bad news.\n\nPlease don't shoot me....", sourceObjectiveStatus = "unverified-source-field" }
quests[14116] = { id = 14116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Uninvited Guest", description = "While you were dealing with the pirates, I noticed the Trade Prince slip upstairs. He's up on the balcony at the top of the stairs.\n\n{name}, I think he's the one that sent the pirates.\n\n<Sassy cringes.>\n\nYou'd better get up there A.S.A.P.! You wouldn't want to keep him waiting.", sourceObjective = "Speak with Trade Prince Gallywix upstairs at the KTC Headquarters main building on Kezan.", completion = "Well, well, well, if it isn't my wayward protege, Mr. {name}.\n\nI'm hurt and disappointed. You didn't send me an invitation to your little party out there. Sorry about the crashers... you know how pirates can be.\n\nSo, shall we get down to business?", sourceObjectiveStatus = "unverified-source-field" }
quests[14117] = { id = 14117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes of Ashenvale", description = "Our enemies abound, {class}, even here at our very doorstep. The night elves have reinforced Talrendis Point in an attempt to stop our advance into Ashenvale. As we speak, their scouts patrol the nearby hills, reporting every movement to and from these gates.\n\nWe must remove these eyes of Ashenvale.\n\nGo. Your prey stalks all around these gates, especially to the east. Slay the scouts who shadow us!", sourceObjective = "Kill 8 Talrendis Scouts.", progress = "Are the hills no longer alive, {class}?", completion = "Excellent. As their scouts fail to report in, Talrendis will feel the terror they've tried in vain to inflict on us.", sourceObjectiveStatus = "unverified-source-field" }
quests[14118] = { id = 14118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venison for the Troops", description = "As we chew up the resources of this land for our war machines, we deprive the local animals of their homes. If they are to die anyway, we should not allow that meat to go to waste. Not when the maw of Orgrimmar gapes open, hungry.\n\nKill the weakened mosshoof stags that remain in this area and collect their meat for our peons and grunts.", sourceObjective = "Collect 15 Slabs of Venison from Weakened Mosshoof Stags.", progress = "You smell of fresh kill, {class}.", completion = "Meat - and lots of it! Well done. This will keep bellies full as we build our arsenal.", sourceObjectiveStatus = "unverified-source-field" }
quests[14120] = { id = 14120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bazillion Macaroons?!", description = "You're an extremely ambitious young goblin, {name}. Maybe a little too ambitious for your own good. I see a lot of myself in you when I was your age.\n\nI have a proposition. You might have noticed that Mount Kajaro is exploding thanks to your dragon. Everyone on Kezan is going to die!\n\nBut, if you bring me a bazillion macaroons before my yacht leaves the island, I'll make sure that you're one of the lucky few to escape.\n\nIf you want to live, you better hurry and figure out how to get me my moolah!", sourceObjective = "Speak with Sassy Hardwrench at KTC Headquarters on Kezan.", completion = "A bazillion macaroons?!?! Where are we going to get that kind of moolah?\n\n<Sassy thinks a moment.>\n\nUm... did the Trade Prince say anything about letting me escape with you on his yacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[14121] = { id = 14121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robbing Hoods", description = "We're all going to die!!!\n\n<You slap Megs to calm her down.>\n\nSorry about that, <Mr./Ms.> {name}. Okay, we need to find a way to get a lot of moolah quickly.\n\nThere are reports of the Trade Prince sending hired looters into the streets.\n\nYou could take the hot rod out there and run them down, snatching the loot that they've illegally stolen. There wouldn't be anything wrong with that, right?", sourceObjective = "Use your Hot Rod to run over 12 Hired Looters, collecting 12 Stolen Loots in the process.", progress = "Were you able to steal a whole bunch of stolen loot?", completion = "Wow, you really did it?! Well, they had it coming, I guess.\n\nThat's an awful lot of loot. Do you think it's enough to get you a spot on the Trade Prince's yacht?\n\nAre you going to be able to bring anyone with you? I don't make too much working in marketing.", sourceObjectiveStatus = "unverified-source-field" }
quests[14122] = { id = 14122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Bank Heist", description = "All of your assets have been frozen and the First Bank of Kezan is out of business!\n\nYou need an awful lot of moolah, boss. I think you're going to have to go break your own money out of the bank! The different widgets in your Goblin All-In-1-Der belt should be enough to crack the vault.\n\nI just hope that you've been saving for a rainy day like I always told you to do. You might have noticed... it's raining hot liquid magma!!!", sourceObjective = "Crack the vault at the First Bank of Kezan to retrieve your Personal Riches.", progress = "Did you get it? Did you crack the safe and get your personal riches out of the bank?", completion = "Hey, you have been saving! I'm so proud of you!\n\n<Sassy counts all of your macaroons.>\n\nUm, boss... this isn't nearly enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[14123] = { id = 14123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waltz Right In", description = "There's only one way we're going to get a bazillion macaroons: stealing from the rich!\n\nThat slime, the Trade Prince, has stolen all kinds of antiques and expensive art. It's time to take them back and give them to the needy... mainly us!\n\nHobart left behind a cap he was working on. It's a disguise that'll make you look like one of Gallywix's mooks. All you have to do is waltz right in to his Villa to the west and 'procure' the items.\n\nJust watch out for his pigs who can smell through the disguise!", sourceObjective = "Obtain Maldy's Falcon, The Goblin Lisa, and The Ultimate Bomb.", progress = "You got the goods, boss?", completion = "Oh, wow! These are worth a fortune.\n\n<Slinky eyes everything with a practiced, greed-filled eye.>\n\nI just hope that the Trade Prince doesn't notice them when you hand them over with the rest of your wealth....", sourceObjectiveStatus = "unverified-source-field" }
quests[14124] = { id = 14124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liberate the Kaja'mite", description = "<Sir/Ma'am>, we need tons of moolah to pay the Trade Prince and get off Kezan! Well, tons of it is just waiting for the taking down there in the Kaja'mine!\n\nThese are the last known deposits of kaja'mite anywhere. This is the raw stuff that made us the genius tinkerers and alchemists we are today. If that's not worth a bazillion macaroons, I don't know what is!\n\nTake some of my kablooey bombs and blowup the deposits. Then, pick up the chunks.\n\nJust watch out for the rebellious trolls!", sourceObjective = "Collect 12 Kaja'mite Chunks.", progress = "How much kaja'mite do you have?", completion = "Nicely done, sir, nicely done! That's a fortune you have there in your bags.\n\nWith all of that, I bet the Trade Prince will let all of us come along on his yacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[14125] = { id = 14125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "447", description = "We're close, but we still don't have enough macaroons. But, I've got a plan: we're going to collect on the headquarters insurance policy!\n\nHope you don't mind, but I filled the place with the leftover fireworks from your party. All you have to do is go in there and sabotage things.\n\nMight I suggest the faulty generator, the leaky stove, and the flammable bed? Then, come back outside and use the control panel to send in the gasbot.\n\nIt's a foolproof plan!", sourceObjective = "Overload the Defective Generator, Activate the Leaky Stove, Drop a Cigar on the Flammable Bed, and use the Gasbot to set KTC Headquarters ablaze!", completion = "This is nothing. You should see Bilgewater Port... the whole thing is going up in flames!\n\nFine, fine, I don't have time to inspect this place. Here's the moolah from the Bilgewater Cartel's insurance policy.\n\nI've got to find a way off the island! Good luck, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14126] = { id = 14126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life Savings", description = "We've got all of the moolah that we need. There's only one thing left to do now, boss: get you to the Trade Prince's yacht. It's about to leave port!\n\nWe're gonna have to hurry. Hop in, 'cause I'm driving!", sourceObjective = "Hand over your Life Savings to Trade Prince Gallywix aboard the Trade Prince's Yacht on Kezan.", progress = "Oh, {name}, it's you. What an unexpected surprise.", completion = "Congratulations, you just made it. I see that you've brought me all that I asked for, including your hot rod.\n\n<The Trade Prince flashes an evil grin.>\n\nA bazillion macaroons couldn't have been easy to come by. I'm now the wealthiest, most powerful, {race} on all of Azeroth!\n\nTOO BAD FOR YOU THAT I'M CHANGING THE TERMS OF OUR DEAL!\n\nYou're now my slave. Get below deck and take a turn shoveling coal. Next stop, Azshara!\n\nMuahahahahahahahaha!", sourceObjectiveStatus = "unverified-source-field" }
quests[14127] = { id = 14127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Highborne?", description = "The wax seal on these orders has been freshly broken. You can't read the carefully-penned night elven script, but a small hand-drawn map indicates the nearby ruins. Underneath the map, written in a different language entirely, are a series of runes penned in a metallic, shimmering ink.\n\nAg'tor will no doubt want to see this important piece of intelligence.", sourceObjective = "Deliver the Scout's Orders to Ag'tor Bloodfist at the rear gate to Orgrimmar.", progress = "You found something on one of the bodies, you say? Give it here!", completion = "<Ag'tor squints at the parchment, turning it in the light.>\n\nNo, I can't make sense of it either, but I don't like what I see. Are these arcane runes?\n\nI'll need you to deliver this to an expert.", sourceObjectiveStatus = "unverified-source-field" }
quests[14128] = { id = 14128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Highborne?", description = "Our blood elven allies have been examining the ruins marked on this map, and can likely understand this mysterious script. Seek out the one called Malynea Skyreaver. She conducts her research from the Orgrimmar Rocketway Exchange just north of here - it's part of the new goblin transit system that snakes across this land. Quickly, now!", sourceObjective = "Deliver the Scout's Orders to Malynea Skyreaver at the Orgrimmar Rocketway Exchange.", progress = "I trust this interruption is in regards to something important?", completion = "What? Give that here, this instant! Ag'tor is correct, these are arcane runes. They're scouting out magical sites? Experimenting with the arcane arts? This is a marked departure from thousands of years of night elven history.\n\nHmph! The idea that they will achieve any competence in this field - even those who once counted themselves among the highborne - is absurd.\n\n<Malynea puts aside the scroll dismissively, but her face is furrowed with concern.>", sourceObjectiveStatus = "unverified-source-field" }
quests[14129] = { id = 14129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runaway Shredder!", description = "I've been trying to impress our new Horde allies with our legendary goblin efficiency, but in hindsight automating the shredders was a bad idea. Now they're mindless killing machines, rampaging over the countryside. Don't get me wrong - that kind of thing has its place - but for the time being I need a brave {class} to help me get these things under control.\n\nIt's easy. Automated shredders, like all machines, must first be beaten into submission. Afterwards, seize the controls and I'll radio you instructions.", sourceObjective = "Attack one of the Runaway Shredders near the rear gates of Orgrimmar and hop inside once it's been significantly damaged.", progress = "<Labor Captain Grabbit's voice crackles over the radio.>\n\nHey {name}! Are you reading this?\n\nPiloting that sucker is easy. Push the pedals for your pedal controls and, ah, move the levers for your lever controls. Got it?", completion = "<Labor Captain Grabbit's voice crackles over the radio.>\n\nHey {name}! Are you reading this?\n\nPiloting that sucker is easy. Push the pedals for your pedal controls and, ah, move the levers for your lever controls. Got it?", sourceObjectiveStatus = "unverified-source-field" }
quests[14130] = { id = 14130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends Come In All Colors", description = "My brothers and I are being hunted.\n\nOur sire was recently killed and the black dragonflight seeks to rout those of us that still live. I'm here to find Azuregos and take him to safety, if only he would let it be that easy.\n\nAzuregos doesn't make many friends, and his taste in them tends to be a bit... unique. The only one I know of here is a murloc named Ergll. You should be able to find him on the coast northeast of here.\n\nDo whatever it takes to find Azuregos and send him to me.\n\nPlease hurry.", sourceObjective = "Locate Ergll on the coast of the Ruins of Arkkoran.", completion = "Hello there! A new friend! So glad to meet you. My name is Ergll. The g is silent.", sourceObjectiveStatus = "unverified-source-field" }
